import type { LiturgyBlock } from '../types';

export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-mol-0001", "section": "service", "who": "rubric", "text": "Авраамию Чухломскому, Галичскому чудотворцу,"},
  {"id": "ru-mol-0002", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0003", "section": "service", "who": "reader", "text": "Перевод: От мирской суеты удалился в тихое пристанище, обитель преподобного Сергия, пришел ты, и там прожив жизнь, подобную ангельской, в землю Галичскую пришел, где насаждая Христову веру и новокрещенных людей от суеверий языческих очищая, многие и великие подвиги ты совершил и, создав четыре обители, монахов собрание отлично упас и ко Христу Спасителю привел ты, Его же моли, преподобный отче Авраамий, спасти души наши."},
  {"id": "ru-mol-0004", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0005", "section": "service", "who": "rubric", "text": "Авраамию, затворнику Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0006", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0007", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0008", "section": "service", "who": "rubric", "text": "Авраамию, архим. Ростовскому,"},
  {"id": "ru-mol-0009", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0010", "section": "service", "who": "reader", "text": "Перевод: Просветившись Божественной благодатью, неверующих людей направил ты к свету Богоразумия, и после смерти сияя светом жизни твоей, источаешь исцеления приходящим с верой к тебе, Авраамий отче наш, Христа Бога моли даровать нам великую милость."},
  {"id": "ru-mol-0011", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0012", "section": "service", "who": "rubric", "text": "Авраамию Смоленскому,"},
  {"id": "ru-mol-0013", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0014", "section": "service", "who": "reader", "text": "Перевод: Сегодня воссияла нам память твоя, прославляемый, как солнце, светозарно лучами озаряющая мир и ночную тьму злых духов от нас отгоняющая. Сегодня Небесные собрания святых Ангелов и души праведных духовно торжествуют, радуясь. Сегодня и мы, грешные, коленопреклоненно молимся: «Отче преподобный Авраамий, Христа Бога моли непрестанно о спасении города и людей с любовью тебя почитающих»."},
  {"id": "ru-mol-0015", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0016", "section": "service", "who": "rubric", "text": "Агапиту Печерскому, врачу безмездному, в Ближних пещерах,"},
  {"id": "ru-mol-0017", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0018", "section": "service", "who": "reader", "text": "Перевод: Подражая смиренномудрию Богоносного Антония, как неким лекарством съедобной травой исцелял болеющих, преподобный Агапит, этим и неверующего врача, заставив уверовать, направил ты на путь спасения. Исцели и наши болезни и молись Господу о прославляющих тебя."},
  {"id": "ru-mol-0019", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0020", "section": "service", "who": "rubric", "text": "Агафону Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0021", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0022", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0023", "section": "service", "who": "rubric", "text": "Александру, игум. Куштскому,"},
  {"id": "ru-mol-0024", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0025", "section": "service", "who": "reader", "text": "Перевод: Всем своим существом захотев послужить Богу, ты поселился в пустынь, в ней же многими трудами и потом ты смог достичь бестелесной, подобной ангельской, жизни, был увиден Богом, удостоился великих чудес в жизни и по преставлении, получив силу отгонять нечистых духов от приходящих к тебе с верой, потому, отче Александр, обо всех нас молись, о спасении наших душ."},
  {"id": "ru-mol-0026", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0027", "section": "service", "who": "rubric", "text": "Александру Ошевенскому,"},
  {"id": "ru-mol-0028", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0029", "section": "service", "who": "reader", "text": "Перевод: Христа, истинного Бога, всей душой ты возлюбил и последовал за Ним с неуклонной волей, все соблазны и сладости мира этого возненавидев, как парящий в небе орел взлетел на Небеса и там с Ангелами воспеваешь и со всеми святыми предстоишь Святой Троице, моли и нам спастись, детям твоим, как обещал, Александр преподобный, отче наш."},
  {"id": "ru-mol-0030", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0031", "section": "service", "who": "rubric", "text": "Александру Свирскому,"},
  {"id": "ru-mol-0032", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0033", "section": "service", "who": "reader", "text": "Перевод: С самой юности, умудренный Богом, устремлением духовным ты поселился в пустыни, пожелав с усердием следовать только по стопам Христа, потому и ангельские чины, видя тебя, удивились, как ты во плоти боролся с коварством невидимых (бесов), победил полчища страстей воздержанием и явился на земле подобным ангелам, Александр преподобный, моли Христа Бога, да спасет наши души."},
  {"id": "ru-mol-0034", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0035", "section": "service", "who": "rubric", "text": "Алексию, человеку Божию,"},
  {"id": "ru-mol-0036", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0037", "section": "service", "who": "reader", "text": "Перевод: Возвысившись в добродетели и очистив ум, ты достиг Желанного и Высочайшего (Христа), украсив же бесстрастием свою жизнь и с чистой совестью приняв на себя подвиг особого поста, в молитвах пребывая как бесплотный ангел, ты воссиял как солнце в мире, преблаженный Алексий."},
  {"id": "ru-mol-0038", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0039", "section": "service", "who": "rubric", "text": "Алипию, иконописцу Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0040", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0041", "section": "service", "who": "reader", "text": "Перевод: Лики святых изображая на досках, их благие дела усердно, как искусный художник, всеми прославляемый Алипий, написал ты на скрижалях своего сердца, и поэтому ты, как икона, прекрасно украшен благодатью священства, как золотым окладом, от Христа Бога и Спасителя душ наших."},
  {"id": "ru-mol-0042", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0043", "section": "service", "who": "rubric", "text": "Алипию Столпнику,"},
  {"id": "ru-mol-0044", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0045", "section": "service", "who": "reader", "text": "Перевод: ерпения ты был столпом, подражавший праотцам, преподобный, Иову — в страданиях, Иосифу — в искушениях, и бесплотных (ангелов) житию, находясь в теле, Алипий отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0046", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0047", "section": "service", "who": "rubric", "text": "Амвросию Оптинскому,"},
  {"id": "ru-mol-0048", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0049", "section": "service", "who": "reader", "text": "Перевод: Как к целебному источнику приходим к тебе, Амвросий, отче наш. Ибо ты на путь спасения нас с верой направляешь, молитвами от бед и напастей охраняешь, в телесных и душевных скорбях утешаешь, более всего же смирению, терпению и любви обучаешь. Моли Человеколюбца Христа и Защитницу усердную о спасении душ наших."},
  {"id": "ru-mol-0050", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0051", "section": "service", "who": "rubric", "text": "Аммону, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0052", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0053", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0054", "section": "service", "who": "rubric", "text": "Амфилохию, Макарию, Тарасию и Феодосию Глушицким,"},
  {"id": "ru-mol-0055", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0056", "section": "service", "who": "reader", "text": "Перевод: Вы явились яркими светильниками, с мудростью оставив земные блага и уйдя во внутреннюю пустынь, Амфилохий, Макарий, Тарасий и Феодосий, научившись смирению и всяческим добродетелям и обретя бессмертие, постом, бдением и прочим воздержанием принося себя Христу, и сейчас на Небесах вы предстоите Престолу Христову. Молите, отцы Богомудрые, Амфилохий, Макарий, Тарасий и Феодосий, мир умиротворить и спастись душам, прославляющим вас, и даровать прощение согрешений почитающим всечестную память вашу."},
  {"id": "ru-mol-0057", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0058", "section": "service", "who": "rubric", "text": "Анастасии Сербской,"},
  {"id": "ru-mol-0059", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0060", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0061", "section": "service", "who": "rubric", "text": "Анатолию, в Ближних пещерах и Анатолию затворнику, в Дальних пещерах, Печерским,"},
  {"id": "ru-mol-0062", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0063", "section": "service", "who": "reader", "text": "Перевод: Преблаженные и Богоносные отцы наши, Анатолий и Анатолий Затворник, как заслуживших дерзновение обращаться ко Господу своим житием, подобным ангельскому, ради него же обогатил Христос нетлением и чудесами мощи ваши, молим вас усердно: «Испросите очищение для наших душ и великую и богатую милость»."},
  {"id": "ru-mol-0064", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0065", "section": "service", "who": "rubric", "text": "Андрею Рублеву, иконописцу,"},
  {"id": "ru-mol-0066", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0067", "section": "service", "who": "reader", "text": "Перевод: Божественного света лучами озаряем, преподобный Андрей, ты Христа познал – Божию Премудрость и Силу и иконою Святой Троицы всему миру проповедал Единого в Трех Ипостасях Бога; мы же с удивлением и радостью взываем тебе: «Имея дерзновение ко Пресвятой Троице, моли о просвещении душ наших!»"},
  {"id": "ru-mol-0068", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0069", "section": "service", "who": "rubric", "text": "Андронику Антиохийскому,"},
  {"id": "ru-mol-0070", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0071", "section": "service", "who": "reader", "text": "Перевод: Пустынным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Андроник: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-0072", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0073", "section": "service", "who": "rubric", "text": "Андронику Московскому,"},
  {"id": "ru-mol-0074", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0075", "section": "service", "who": "reader", "text": "Перевод: Безмолвие с юности возлюбив, на гору Маковец пришел ты, Андроник блаженный, общежительную обитель устроил в земном городе Москва, в обители Небесного града сейчас торжествуешь, молись Христу Богу о спасении наших душ."},
  {"id": "ru-mol-0076", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0077", "section": "service", "who": "rubric", "text": "Андронику и Савве Московским,"},
  {"id": "ru-mol-0078", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0079", "section": "service", "who": "reader", "text": "Перевод: С юности своей, преподобные отцы Андроник и Савва, в пустынь вселились Сергия великого, его житию последовав, плоды смирения и послушания вы возрастили, потому удостоившись быть строителями и начальниками устроенного по обету монастыря святителя Алексия, с ним же испросите у Христа Бога верующим людям здоровье и спасение, и душам нашим великую милость."},
  {"id": "ru-mol-0080", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0081", "section": "service", "who": "rubric", "text": "Андронику, Савве и Александру Московским, Даниилу Черному, Андрею Рублеву,"},
  {"id": "ru-mol-0082", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0083", "section": "service", "who": "reader", "text": "Перевод: Плоды добродетелей принеся на земле, преподобные отцы, в Небесных чертогах сейчас благоухаете, как райские цветы, и лицом к лицу созерцаете Пресвятую Троицу, Ее же с дерзновением молите о спасении наших душ."},
  {"id": "ru-mol-0084", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0085", "section": "service", "who": "rubric", "text": "Антонию Великому,"},
  {"id": "ru-mol-0086", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0087", "section": "service", "who": "reader", "text": "Перевод: Ревнителю Илии нравом подражая, за Крестителем прямыми путями следуя, отче Антоний, ты сделался обитателем пустыни и вселенную утвердил молитвами твоими. Потому ходатайствуй пред Христом Богом о спасении душ наших."},
  {"id": "ru-mol-0088", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0089", "section": "service", "who": "rubric", "text": "Антонию Дымскому,"},
  {"id": "ru-mol-0090", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0091", "section": "service", "who": "reader", "text": "Перевод: Добродетелей ревнитель, пустынный житель, подвижник веры во Христа Бога нашего, пощением и трудами умертвивший плотские вожделения, одноименный с Антонием Великим, его житию ты подражал и в его же имя воздвиг Божественный храм, вместе с ним, преподобный Антоний, моли Спасителя всех, да и нас сделает победителями плотских похотей и храмами Святого Духа по великой Его милости."},
  {"id": "ru-mol-0092", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0093", "section": "service", "who": "rubric", "text": "Антонию Печерскому, Киевскому, начальнику всех русских монахов,"},
  {"id": "ru-mol-0094", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0095", "section": "service", "who": "reader", "text": "Перевод: От мирской суеты ты ушел, отвержением же мира евангельски последовал Христу и, прожив жизнь, подобную ангельской, достиг тихого пристанища Святой Горы Афон. Оттуда же по благословению отцов пришел на Киевскую гору, и там, наполнив жизнь трудолюбием, Отечество твое просветил ты, и множеству монашествующих показал путь, ведущий к Небесному Царствию, привел их ко Христу, Его же моли, Антоний преподобный, да спасет души наши."},
  {"id": "ru-mol-0096", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0097", "section": "service", "who": "rubric", "text": "Антонию Римлянину, Новгородскому чдтв.,"},
  {"id": "ru-mol-0098", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0099", "section": "service", "who": "reader", "text": "Перевод: Древний Рим, отечество твое, оставив, на камень, как на быстрый корабль, ты взошел и на нем превыше законов природы, как бесплотный, по воде ты путешествовал, руководимый промышлением Божественного разума, Великого Новгорода достиг ты и, обитель в нем создав, тело твое в ней предал Богу, как священный дар. Потому молим тебя, отче Антоний, моли Христа Бога, да спасет души наши."},
  {"id": "ru-mol-0100", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0101", "section": "service", "who": "rubric", "text": "Антонию Сийскому,"},
  {"id": "ru-mol-0102", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0103", "section": "service", "who": "reader", "text": "Перевод: Стремлением духовным воспламенившись и суету мирскую отринув, к Единственному Богу с любовью привязался ты и Его всей душой взыскуя, во внутреннюю пустынь ушел ты, поселившись у воды, где в слезах и трудах пребывая долгие годы, со многим терпением ангельскую жизнь проводил ты, наставляемый Божественным Разумом, и множество монахов собрал ты, мудрый, их же посещать не переставай, Антоний, преподобный отче наш, Пресвятой Троице молясь от всякого зла избавить и спасти души наши."},
  {"id": "ru-mol-0104", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0105", "section": "service", "who": "rubric", "text": "Антонию и Феодосию Печерским,"},
  {"id": "ru-mol-0106", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0107", "section": "service", "who": "reader", "text": "Перевод: Двоих первых российских светил почтим: Антония, Богом посланного и Феодосия, Богом дарованного. Ибо они первые, просияв жизнью, подобной ангельской, от Киевских гор осветили все концы нашего Отечества и показали многим правильный путь к Небесам, и были первыми отцами для монахов, приведя к Богу ряды спасаемых, и сейчас, предстоя в Небесах немеркнущему Свету Бога, молятся о душах наших."},
  {"id": "ru-mol-0108", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0109", "section": "service", "who": "rubric", "text": "Арефе, затворнику Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0110", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0111", "section": "service", "who": "reader", "text": "Перевод: Богатство твое душевное враг хотел погубить и сначала помрачил тебя богатством тленным, но спасающий всех Господь попустил кражу земного богатства, душевное же сохранил невредимым, явив тебя наследником Небесных сокровищ, Арефа, потому тебя почитаем и прославляем."},
  {"id": "ru-mol-0112", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0113", "section": "service", "who": "rubric", "text": "Аркадию Новоторжскому,"},
  {"id": "ru-mol-0114", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0115", "section": "service", "who": "reader", "text": "Перевод: Руководимый духовным наставником, преподобным отцом Ефремом, прекрасный ревнитель послушания, отче Аркадий, ты удалился от мирской суеты и был превосходным монахом, усердно подвизаясь, от Христа Бога получил ты венец славы Небесной и сейчас, вместе с преподобным отцом Ефремом у Престола Всевышнего предстоя, молись о нас, об избавлении нашем от всех бед и скорбей и о спасении душ наших."},
  {"id": "ru-mol-0116", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0117", "section": "service", "who": "rubric", "text": "Арсению Великому,"},
  {"id": "ru-mol-0118", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0119", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню и из глубины стенаниями плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Арсений, отче наш; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0120", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0121", "section": "service", "who": "rubric", "text": "Арсению Каппадокийскому,"},
  {"id": "ru-mol-0122", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0123", "section": "service", "who": "reader", "text": "Перевод: Жизнь богоугодную прекрасно завершив, ты стал почитаемым вместилищем Утешителя, Богоносный Арсений, получив благодать чудотворений, ты всем подаешь быструю помощь, отче преподобный, Христу Богу молись даровать нам великую милость."},
  {"id": "ru-mol-0124", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0125", "section": "service", "who": "rubric", "text": "Арсению Комельскому,"},
  {"id": "ru-mol-0126", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0127", "section": "service", "who": "reader", "text": "Перевод: Ты удалился от мира и поселился в пустыни, и там подвизался прекрасным подвигом, постом, и молитвами, и многим терпением, в жизни своей явив многие чудеса, и после успения источаешь различные исцеления с верой приходящим к почитаемому гробу твоему, Арсений, отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0128", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0129", "section": "service", "who": "rubric", "text": "Арсению Коневскому,"},
  {"id": "ru-mol-0130", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0131", "section": "service", "who": "reader", "text": "Перевод: Направляемый Духом Божиим, ты полюбил безмолвие, в котором, по Евангелию подвизающемуся, удивительный Афонский дар — икона Богоматери даровалась тебе, всеблаженный, и примером добродетелей был стаду твоему, Арсений отче наш, к Небесному торжеству ты поднялся, где, радуясь с Ангелами, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0132", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0133", "section": "service", "who": "rubric", "text": "Арсению Новгородскому,"},
  {"id": "ru-mol-0134", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0135", "section": "service", "who": "reader", "text": "Перевод: Отечество свое и родных оставив, ты предал себя Христу и достиг Великого Новгорода, и в нем в юродстве трудолюбивое тело твое изнурил многим постом и воздержанием, и удостоился принять дар пророчества, и предпочел носить на себе залатанные одежды, и, телом в Новгороде пребывая, обитель себе в Царствии Небесном у Христа, Бога всех, ты создал. Его же моли, святой Арсений преподобный, Церкви и стране нашей в мире пребывать от всех козней вражеских, оказать милость к нам, почитающим твое торжество, и спасти души наши."},
  {"id": "ru-mol-0136", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0137", "section": "service", "who": "rubric", "text": "Арсению Трудолюбивому, в Дальних пещерах,"},
  {"id": "ru-mol-0138", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0139", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню и из глубины стенаниями плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Арсений, отче наш; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0140", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0141", "section": "service", "who": "rubric", "text": "Афанасию Афонскому,"},
  {"id": "ru-mol-0142", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0143", "section": "service", "who": "reader", "text": "Перевод: Житию твоему во плоти удивились ангельские воинства: как ты, в тело облеченный, вступил в борьбу с невидимым врагом и поразил демонов полки, всехвальный. За то, Афанасий, Христос тебе богатыми дарованиями воздал; потому, отче, ходатайствуй [пред Христом Богом] о спасении душ наших."},
  {"id": "ru-mol-0144", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0145", "section": "service", "who": "rubric", "text": "Афанасию Высоцкому (Младшему), Серпуховскому,"},
  {"id": "ru-mol-0146", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0147", "section": "service", "who": "reader", "text": "Перевод: Образ Божий в богосотворенной душе твоей: ум, слово и дух сохраняя, устремился ты, отче преподобный Афанасий, любовью к Творцу всего Богу, и потому молитвы, труды и подвиги добродетельные совершив, переселился ты в вечные небесные обители. Оттуда же наблюдай за нами, моля Святую Троицу, о том, чтобы нам наследовать небесное всерадостное блаженство."},
  {"id": "ru-mol-0148", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0149", "section": "service", "who": "rubric", "text": "Афанасию, затворнику Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0150", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0151", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0152", "section": "service", "who": "rubric", "text": "Афанасию, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0153", "section": "service", "who": "rubric", "text": "глас 7"},
  {"id": "ru-mol-0154", "section": "service", "who": "reader", "text": "Перевод: Согласно имени твоему (Афанасий от греч. Ἀθανάσιος — бессмертный), за труды великие и постоянное твое умерщвление плоти в затворе, бессмертную сейчас на Небесах жизнь наследовавший, молим тебя усердно, молись о нас, чтобы и нам удостоиться ее получить."},
  {"id": "ru-mol-0155", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0156", "section": "service", "who": "rubric", "text": "Афанасию и Феодосию Череповецким,"},
  {"id": "ru-mol-0157", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0158", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0159", "section": "service", "who": "rubric", "text": "Ахиле, диакону Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0160", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0161", "section": "service", "who": "reader", "text": "Перевод: Постническую жизнь возлюбив и многие труды с младых ногтей на себя возложив, в диаконский сан был возведен, всеми почитаемый, в нем послужил ты в церкви Божией Матери непорочно, Ее же моли о спасении душ наших."},
  {"id": "ru-mol-0162", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0163", "section": "service", "who": "rubric", "text": "Боголепу, отроку, схимонаху Черноярскому, Астраханскому,"},
  {"id": "ru-mol-0164", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0165", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0166", "section": "service", "who": "rubric", "text": "Варлааму Важскому, Шенкурскому,"},
  {"id": "ru-mol-0167", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0168", "section": "service", "who": "reader", "text": "Перевод: Заботой о добродетелях ты обуздал буйство плоти, правильным образом действий душу свою украсив, от земного ты возвел свой ум ко Христу, потому Он явил тебя обильным потоком исцелений для приходящих к тебе с верой и благоговейно взывающих: «Варлаам, отче наш, моли Христа Бога, да спасет души наши»."},
  {"id": "ru-mol-0169", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0170", "section": "service", "who": "rubric", "text": "Варлааму Индийскому,"},
  {"id": "ru-mol-0171", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0172", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню, и стенаниями из глубины плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Варлаам, отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0173", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0174", "section": "service", "who": "rubric", "text": "Варлааму Керетскому,"},
  {"id": "ru-mol-0175", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0176", "section": "service", "who": "reader", "text": "Перевод: Божественной свыше просветившись благодатью, преподобный, мир оставил ты, житейскую печаль и всякую суету мира этого ради любви Христовой с дерзновением ты отверг, евангельски Христу последовал ты и, взяв Его ярмо, во всем повиновался Его воле и весь разум и сердце к Нему неизменно направлял, Христа ради тело свое изнуряя постом и бдением, в молитвах своих бодрствуя, умилостивляя Бога и представляя перед собой Пречистую Богородицу Молитвенницей, потому ты получил от Бога власть и силу против врага, не побоялся непогоды, морских трудностей и холода, морем в небольшом корабле по воде путешествуя, противостоя сильным бурям, направляемый промыслом Божественного разума, и около мыса Святой Нос непроходимый морской путь от ядовитых червей очистил ты, сделав его безопасным, молитвами своими и многим терпением во временной жизни подвиг совершил ты и прожил подобно ангелам, потому и после успения источаешь благодать чудес для всех с верой приходящих к тебе, Варлаам, преблаженный отче наш, взываем к тебе: моли Христа Бога, да спасет души наши."},
  {"id": "ru-mol-0177", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0178", "section": "service", "who": "rubric", "text": "Варлааму, игумену Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0179", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0180", "section": "service", "who": "reader", "text": "Перевод: Блага мира и славу его оставив, пришел ты в пещеру, где преуспевая от силы в силу (Пс.83:8), был вождем Христова стада, всеми прославляемый Варлаам, которое ты прекрасно упас, так и нас упаси, молим тебя, сохраняя от всех зол, да прославляем тебя."},
  {"id": "ru-mol-0181", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0182", "section": "service", "who": "rubric", "text": "Варлааму Хутынскому,"},
  {"id": "ru-mol-0183", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0184", "section": "service", "who": "reader", "text": "Перевод: Сном на земле, пощением и бдением тело твое изнуряя, преподобный, все плотские помышления ты умертвил и стал обильным потоком исцелений с верой приходящим к тебе, Варлаам, отче наш, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0185", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0186", "section": "service", "who": "rubric", "text": "Варнаве Ветлужскому,"},
  {"id": "ru-mol-0187", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0188", "section": "service", "who": "reader", "text": "Перевод: Стремлением духовным разжигаем, отринув мирскую суету, ты неотлучно с любовью присоединился к Богу. И Его всею душой взыскуя, удалился во внутреннюю пустынь, поселился у воды, где в слезах и трудах многие годы пребывая, во многом терпении ты проводил ангельское житие, наставляемый Божественным разумом, и множество монахов собрал ты, мудрый. Не переставай оказывать им внимание, Варнава преподобный, отче наш, молясь Пресвятой Троице об избавлении от всяческого зла и спасении наших душ."},
  {"id": "ru-mol-0189", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0190", "section": "service", "who": "rubric", "text": "Варнаве Гефсиманскому,"},
  {"id": "ru-mol-0191", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0192", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0193", "section": "service", "who": "rubric", "text": "Василию Декаполиту, исп.,"},
  {"id": "ru-mol-0194", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0195", "section": "service", "who": "reader", "text": "Перевод: Житель пустыни – ты и телом подобен Ангелам, и чудотворцем стал, Богоносный отец наш, Василий. Постом, бдением, молитвой приняв Небесные дарования, исцеляешь больных и души приходящих к тебе с верой. Слава Давшему тебе силу, слава Венчавшему тебя, слава Подающему через тебя всем исцеление."},
  {"id": "ru-mol-0196", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0197", "section": "service", "who": "rubric", "text": "Вассиану и Ионе Пертоминским, Соловецким чдтвв.,"},
  {"id": "ru-mol-0198", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0199", "section": "service", "who": "reader", "text": "Перевод: Сначала вы отвергли мир, как морской бури его избежав, отцы преподобные, потом же, по воле Божией, приняли блаженную кончину в морских водах и к безболезненному покою преставились от земли, радуясь. Потому и после кончины прославились от Христа Бога обильными чудесами, явились усердными помощниками в бедах верующим и сейчас на Небесах, предстоя Престолу Христову, Вассиан преблаженный и Иона преславный, молитесь всегда о душах наших."},
  {"id": "ru-mol-0200", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0201", "section": "service", "who": "rubric", "text": "Вениамину Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0202", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0203", "section": "service", "who": "reader", "text": "Перевод: Ты был хорошим купцом (Мф.13:45-46), Богомудрый Вениамин, ибо раздав свое тленное богатство, приобрел тем самым нетленное — в Царствии Небесном, его же благами наслаждаясь сейчас в изобилии, проси нам мира и великой милости."},
  {"id": "ru-mol-0204", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0205", "section": "service", "who": "rubric", "text": "Гавриилу Седмиезерскому,"},
  {"id": "ru-mol-0206", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0207", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0208", "section": "service", "who": "rubric", "text": "Галактиону Вологодскому,"},
  {"id": "ru-mol-0209", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0210", "section": "service", "who": "reader", "text": "Перевод: Сегодня город Вологда тобой всему миру похваляется, ибо ты воссиял ярко, как солнце, и чудесами твоими города и села, преподобный Галактион, озарил ты. И сейчас молись Господу об избавлении душ наших от обольщения вражеского, о спасении города нашего от нападения язычников и прочих противников, и испроси у Христа Бога всем с любовью почитающим тебя прощение прегрешений и просящим твоей помощи от всякой скорби избавление, взывающим к тебе: «Бог наш с нами, изволивший прославить угодника Своего»."},
  {"id": "ru-mol-0211", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0212", "section": "service", "who": "rubric", "text": "Геннадию Костромскому и Любимоградскому,"},
  {"id": "ru-mol-0213", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0214", "section": "service", "who": "reader", "text": "Перевод: Как голубь пустыннолюбивый, от суетного и беспокойного мира в пустынь удалился, чистотой и говением, молитвами и трудами прославил ты Бога душой и телом своим. И так благочестиво прожив, явился ты, преподобный Геннадий, пустыни Любимоградской украшением, монахам почтенной жизни примером и горячим молитвенником обо всех, приходящих к тебе с верой."},
  {"id": "ru-mol-0215", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0216", "section": "service", "who": "rubric", "text": "Герасиму Вологодскому,"},
  {"id": "ru-mol-0217", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0218", "section": "service", "who": "reader", "text": "Перевод: Равный по образу Бесплотным Силам [ангелам] и преподобным единомышленник, преподобный Герасим, один ты пришел на реку Вологду, предсказывая там быть великому городу, и в нем построиться святой церкви, и святителям там появиться. Потому и удостоился ты быть погребенным около того города, и после смерти твоей многими чудесами исцелений ты прославился. Молись всегда о нас, чтобы получить нам от Бога милость."},
  {"id": "ru-mol-0219", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0220", "section": "service", "who": "rubric", "text": "Герману Аляскинскому,"},
  {"id": "ru-mol-0221", "section": "service", "who": "rubric", "text": "глас 7"},
  {"id": "ru-mol-0222", "section": "service", "who": "reader", "text": "Перевод: Звезда преяркая Церкви Христовой, на севере просиявшая, всех к Царству Небесному путеводящая, учитель и апостол истинной веры, ходатай и защитник гонимых, украшение превосходное Святой Церкви в Америке, преподобный отче Герман Аляскинский, молись ко Господу Спасителю нашему о спасении душ наших."},
  {"id": "ru-mol-0223", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0224", "section": "service", "who": "rubric", "text": "Герману Соловецкому,"},
  {"id": "ru-mol-0225", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0226", "section": "service", "who": "reader", "text": "Перевод: Стремлением духовным с юности воспламеняем, преподобный Герман, Христу ты последовал тесным жизненным путем и на морском пустынном острове, как в тихом пристанище, ты поселился, в нем многие годы постнически прожил ты, вместе с блаженными отцами Зосимой и Савватием, с ними же моли Христа Бога о нас, с любовью почитающих святую память твою."},
  {"id": "ru-mol-0227", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0228", "section": "service", "who": "rubric", "text": "Геронтию, канонарху Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0229", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0230", "section": "service", "who": "reader", "text": "Перевод: Достойный особого почитания канонарх Геронтий, первым возглашавший правило (греч. κᾰνών = правило, канон) в церкви и в монашеском правиле воссиявший ярко, моли Христа Бога, чтобы Он подал душам нашим отпущение прегрешений."},
  {"id": "ru-mol-0231", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0232", "section": "service", "who": "rubric", "text": "Геронию и Леонтию, канонархам Печерским, в Дальних пещерах,"},
  {"id": "ru-mol-0233", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0234", "section": "service", "who": "reader", "text": "Перевод: Двое святых, в церкви первыми возглашавшие правило и в монашеском правиле воссиявшие ярко, молите Христа Бога, чтобы Он подал душам нашим отпущение прегрешений."},
  {"id": "ru-mol-0235", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0236", "section": "service", "who": "rubric", "text": "Григорию, священноиноку,"},
  {"id": "ru-mol-0237", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0238", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0239", "section": "service", "who": "rubric", "text": "Григорию Декаполиту,"},
  {"id": "ru-mol-0240", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0241", "section": "service", "who": "reader", "text": "Перевод: Ты был примером воздержания, Божественным Духом все просветив, православно совершил жизненный путь, учением мир просветил и обличил замыслы еретиков, отче преподобный Григорий, Христа Бога моли даровать нам великую милость."},
  {"id": "ru-mol-0242", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0243", "section": "service", "who": "rubric", "text": "Григорию и Кассиану Авнежским,"},
  {"id": "ru-mol-0244", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0245", "section": "service", "who": "reader", "text": "Перевод: Православия наставники, благочестия и чистоты учителя, церкви Вологодской дарованное Богом украшение, преподобные отцы наши Григорий и Кассиан, молите Милостивого Бога, да вашим предстательством подаст благодать и мир стране нашей и душам нашим спасение."},
  {"id": "ru-mol-0246", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0247", "section": "service", "who": "rubric", "text": "Григорию Пельшемскому, Вологодскому чдтв.,"},
  {"id": "ru-mol-0248", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0249", "section": "service", "who": "reader", "text": "Перевод: Любовью ко Христу, Богомудрый, просветившись, ты просиял добродетелями и, всякое наслаждение плотское возненавидев в пустыни поселился, в ней же весьма подвизался в жизни этой временной — в молитвенных песнопениях, бдении и пощении, потому и Христос даром чудес обогатил тебя, но вспоминай нас, почитающих пресветлую память твою, преподобный отче Григорий, и моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0250", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0251", "section": "service", "who": "rubric", "text": "Григорию, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0252", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0253", "section": "service", "who": "reader", "text": "Перевод: Пещерным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Григорий: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-0254", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0255", "section": "service", "who": "rubric", "text": "Григорию, чудотворцу Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0256", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0257", "section": "service", "who": "reader", "text": "Перевод: Великие дарования получивший и великие чудеса силой Божией творивший, пречудный отче Григорий, имея великое дерзновение ко Христу Богу, непрестанно о нас молись Ему, да грехов прощение подаст душам нашим."},
  {"id": "ru-mol-0258", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0259", "section": "service", "who": "rubric", "text": "Дамиану пресвитеру, целебнику, Иеремии и Матфею прозорливым, Печерским, в Ближних пещерах,"},
  {"id": "ru-mol-0260", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0261", "section": "service", "who": "reader", "text": "Перевод: Христовых заповедей светом сердца свои просветив, мрак страстей разогнали вы, потому стали жилищем Троицы, трое отцов, Дамиан, Иеремия и Матфей, от Нее же получив благодать, больных исцеляете, будущее возвещаете и, совместно с ангелами, молитесь Христу Богу даровать нам приобщение к святым."},
  {"id": "ru-mol-0262", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0263", "section": "service", "who": "rubric", "text": "Даниилу Переяславскому,"},
  {"id": "ru-mol-0264", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0265", "section": "service", "who": "reader", "text": "Перевод: С юности, блаженный, всего себя посвятив Господу, всегда повинуясь Богу и противясь диаволу, ты победил греховные страсти, тем самым став храмом Божиим и воздвигнув прекрасную обитель во славу Пресвятой Троицы и собранное тобой в ней стадо Христово Богоугодно упас, преставился ты к вечным обителям, отче Даниил. Моли Триипостасного во Единой Сущности Бога о спасении душ наших."},
  {"id": "ru-mol-0266", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0267", "section": "service", "who": "rubric", "text": "Даниилу Столпнику,"},
  {"id": "ru-mol-0268", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0269", "section": "service", "who": "reader", "text": "Перевод: Терпения ты сделался столпом, подражая праотцам, преподобный: Иову – в страданиях, Иосифу – в искушениях, и жизни бесплотных – пребывая во плоти, Даниил отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0270", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0271", "section": "service", "who": "rubric", "text": "Дию Константинопольскому,"},
  {"id": "ru-mol-0272", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0273", "section": "service", "who": "reader", "text": "Перевод: Пустынным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Дий: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-0274", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0275", "section": "service", "who": "rubric", "text": "Димитрию Прилуцкому, Вологодскому чдтв,"},
  {"id": "ru-mol-0276", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0277", "section": "service", "who": "reader", "text": "Перевод: Свыше от Бога, преподобный, благодать получил ты духовную, и от Него был познан (1Кор.13:12), блаженный, ради Него и ты духовно познал лучшее Его, жизнь Будущего века, постнически испытав себя в своих обителях. И сейчас, с ангелами радуясь, Спасителю всех о нас молись, святой Димитрий, да все взываем к тебе: «Слава Давшему тебе силу, слава Венчавшему тебя, слава Подающему через тебя всем исцеления»."},
  {"id": "ru-mol-0278", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0279", "section": "service", "who": "rubric", "text": "Тому же святому (Сретение образа прп. Димитрия),"},
  {"id": "ru-mol-0280", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0281", "section": "service", "who": "reader", "text": "Перевод: Воссиял сегодня, как солнце, почитаемый образ подобающей твоей святости иконы, более чем солнце лучами чудес твоих всех озаряя, тьму бесовскую разгоняя, его же с радостью встречая, образуя духовное собрание, непрестанно взываем к тебе: «Димитрий, отче наш, моли Спасителя всех сохранить город твой и страну нашу, стаду твоему спасение подавая и великую милость»."},
  {"id": "ru-mol-0282", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0283", "section": "service", "who": "rubric", "text": "Диодору Юрьегорскому,"},
  {"id": "ru-mol-0284", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0285", "section": "service", "who": "reader", "text": "Перевод: Духовным устремлением возгоревшись, мирскую суету отвергнув, к Единому Богу ты привязался любовью и Его всей душой взыскуя, во внутреннюю пустынь ушел, поселился у воды, где в слезах и трудах пребывая долгие годы, со многим терпением совершал подобное ангельскому житие, руководимый Божественным разумом, стадо монахов собрал, мудрый, не переставай посещать их, Диодор преподобный, отче наш, Пресвятой Троице молясь от зол всяческих избавиться и спасти души наши."},
  {"id": "ru-mol-0286", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0287", "section": "service", "who": "rubric", "text": "Дионисию, игумену Глушицкому,"},
  {"id": "ru-mol-0288", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0289", "section": "service", "who": "reader", "text": "Перевод: Любовью к Богу с юности разжигаем, Дионисий преподобный, все земные блага возненавидев, Христа единого ты возлюбил и ради Него поселился во внутреннюю пустынь, и жил со зверями, весь Христов. Поэтому Всевидящее Око, увидев твои труды, по преставлении обогатил тебя даром чудотворений. Потому взываем к тебе: «Моли непрестанно обо всех нас, почитаемую твою память всегда в молитвенных песнопениях прославляющих»."},
  {"id": "ru-mol-0290", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0291", "section": "service", "who": "rubric", "text": "Дионисию и Амфилохию Глушицким,"},
  {"id": "ru-mol-0292", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0293", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0294", "section": "service", "who": "rubric", "text": "Дионисию, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0295", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0296", "section": "service", "who": "reader", "text": "Перевод: Жертву Бескровную приносивший Господу безукоризненно и служивший Ему по призванию своему долгое время неленостно, святой Дионисий, молись о нас, с любовью почитающих тебя."},
  {"id": "ru-mol-0297", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0298", "section": "service", "who": "rubric", "text": "Дионисию Радонежскому,"},
  {"id": "ru-mol-0299", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0300", "section": "service", "who": "reader", "text": "Перевод: Все земное, привлекающее взоры любителей мира, ты возненавидел, отче Богоносный Дионисий, оценив это как сор, шествуя путем скорбей, и в терпении ты явился хорошим воином Христовым, победив страсти мира, ты до своей смерти оставался непоколебимым защитником благочестия. Потому мы сегодня, празднуя священную память твою, прославляем тебя духовными песнопениями и смиренно молим: предстоя Престолу Господа Бога, да ходатайствуешь о спасении наших душ."},
  {"id": "ru-mol-0301", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0302", "section": "service", "who": "rubric", "text": "Досифею Верхнеостровскому, Псковскому,"},
  {"id": "ru-mol-0303", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0304", "section": "service", "who": "reader", "text": "Перевод: Как светильник преяркий явился ты на острове Псковского озера, преподобный отче наш Досифей. Ибо ты крест Христов с юности своей на плечи взяв, усердно Ему последовал, приблизившись чистотой к Богу, потому и даром чудотворений обогатился ты. Поэтому и мы, приходя к святой иконе твоей, сокрушаясь, взываем: «Отче преподобный, моли Христа Бога о спасении душ наших»."},
  {"id": "ru-mol-0305", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0306", "section": "service", "who": "rubric", "text": "Евфимию Архангелогородскому,"},
  {"id": "ru-mol-0307", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0308", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0309", "section": "service", "who": "rubric", "text": "Евфимию Великому,"},
  {"id": "ru-mol-0310", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0311", "section": "service", "who": "reader", "text": "Перевод: Веселись, пустыня нерождающая, возрадуйся, не мучившаяся родами, ибо умножил тебе детей муж стремлений духовных, благочестием их насадив, воздержанием воспитав к совершенству в добродетелях. Его мольбами, Христе Боже, спаси души наши."},
  {"id": "ru-mol-0312", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0313", "section": "service", "who": "rubric", "text": "Евфимию, схимнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0314", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0315", "section": "service", "who": "reader", "text": "Перевод: Евфимий почитаемый, преподобным подражатель и ангелам собеседник, заслуживший вместе с ними своей чистой и безмолвной жизнью вечные блага, молись Господу всегда обо всех нас, чтобы и мы удостоились тех же благ."},
  {"id": "ru-mol-0316", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0317", "section": "service", "who": "rubric", "text": "Евфимию, архим. Суздальскому, чдтв.,"},
  {"id": "ru-mol-0318", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0319", "section": "service", "who": "reader", "text": "Перевод: Как сияющая звезда, пришел ты с востока на запад, оставив родину свою, Нижний Новгород, и дойдя до Богоспасаемого города Суздаля. В нем ты основал обитель и собрал множество монахов и, получив дар чудотворений от Бога, отче Евфимий, был единомысленным о Христе и постником наравне с преподобным Сергием. С ним же у Христа Бога испроси нам здоровья, спасения и душам нашим великую милость."},
  {"id": "ru-mol-0320", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0321", "section": "service", "who": "rubric", "text": "Евфимию и Харитону Сянжемским,"},
  {"id": "ru-mol-0322", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0323", "section": "service", "who": "reader", "text": "Перевод: Пустынную и безмолвную жизнь вы постнически проводили, Христов крест на плечо подняв и по Его стопам усердно последовав, против невидимого врага мужественно вооружились и его козни сокрушили, молитвами и слезами, в чистоте к Богу приблизившись, преподобные отцы наши Евфимий и Харитон. Как солнце сияете вы светозарными лучами чудес ваших и, как имеющие дерзновение ко Спасителю, мир испросите для мира и спасение душам нашим."},
  {"id": "ru-mol-0324", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0325", "section": "service", "who": "rubric", "text": "Евфросину Псковскому,"},
  {"id": "ru-mol-0326", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0327", "section": "service", "who": "reader", "text": "Перевод: Житейские заботы и всякую суету этого мира ради любви Христовой с дерзновением ты отверг, блаженный, и выполнил всё, что повелел распятый Господь Иисус Христос, и, подняв Его ярмо, во всем повиновался Его воле и, благочестиво трудясь, ты с усердием исполнял жизненные заповеди Христовы. И потому Бог прославил тебя и после смерти явил чудеса от почитаемого гроба твоего. Поэтому неоскудеваемой и плодородной стала обитель твоя, и была для нищих богатым пристанищем и защитой, отче наш преподобный Евфросин, моли Христа Бога, да спасет души наши."},
  {"id": "ru-mol-0328", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0329", "section": "service", "who": "rubric", "text": "Евфросинии, в миру Евдокии, вел. кн. Московской,"},
  {"id": "ru-mol-0330", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0331", "section": "service", "who": "reader", "text": "Перевод: После земного вдовства ты сделала себя невестой Небесному Жениху и в княжеских палатах жила подвижнически, а после и палаты, и детей твоих оставила ради Бога, преподобная Евфросиния, и, поселившись в созданной тобой обители, в монашеском образе ты явила многие подвиги и святую твою жизнь по благодати Божией увенчала блаженной кончиной. И сейчас, предстоя Христу Богу, моли о спасении наших душ."},
  {"id": "ru-mol-0332", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0333", "section": "service", "who": "rubric", "text": "Евфросинии, игумении Полоцкой,"},
  {"id": "ru-mol-0334", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0335", "section": "service", "who": "reader", "text": "Перевод: В двенадцатилетнем возрасте, подражая двенадцатилетнему Христу, учившему в Храме слову Божию (Лк.2:41-49), ты последовала за Ним, Евфросиния. Временную славу и земного жениха оставив и все мирское презрев, ты обручила себя Тому, кто прекраснее всех — Христу. Подняв крест, шествуя путем ангельской жизни и многих к Нему наставляя, в благоухании мира ты поднялась в Царствие Небесное, где моли, Кого возлюбила ты, о почитающих благочестиво память твою."},
  {"id": "ru-mol-0336", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0337", "section": "service", "who": "rubric", "text": "Евфросинии Суздальской,"},
  {"id": "ru-mol-0338", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0339", "section": "service", "who": "reader", "text": "Перевод: Святая твоя память Суздальский край радует, верующих же всех созывает в почитаемый храм твой, где сегодня празднуется прославляемая всеми память твоя, Евфросиния преподобная, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0340", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0341", "section": "service", "who": "rubric", "text": "Елеазару Анзерскому,"},
  {"id": "ru-mol-0342", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0343", "section": "service", "who": "reader", "text": "Перевод: Ты отверг тленное и телесное, стараясь достичь нетленного и, удалившись от мира, поселился на морском острове, где усердно многие годы Господу трудился, потому и дарами прозрения и чудес обогатился ты, отче преподобный Елиазар. Христа Бога моли даровать нам мир и великую милость."},
  {"id": "ru-mol-0344", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0345", "section": "service", "who": "rubric", "text": "Елисею Лавришевскому и свт. Лаврентию, затворнику Печерскому, еп. Туровскому, в Ближних пещерах,"},
  {"id": "ru-mol-0346", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0347", "section": "service", "who": "reader", "text": "Перевод: Преподобный отче наш Елисей, с Лаврентием удивительным подвизался ты, учителю своему подражая, земную славу и честь повергли вы под ноги Христа, потому Господь увенчал вас нетленным венцом славы Своей."},
  {"id": "ru-mol-0348", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0349", "section": "service", "who": "rubric", "text": "Еразму Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0350", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0351", "section": "service", "who": "reader", "text": "Перевод: Благолепие дома Господа возлюбив, потратил ты без жалости имение свое на украшение его, преподобный Еразм, потому сейчас, живя в доме Господа на Небесах, моли и нам освятиться в жилище Господа."},
  {"id": "ru-mol-0352", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0353", "section": "service", "who": "rubric", "text": "Ефрему Новоторжскому,"},
  {"id": "ru-mol-0354", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0355", "section": "service", "who": "reader", "text": "Перевод: Ты просветился свыше Божественной благодатью, Богомудрый, и после смерти проявилась светлость жития твоего, потому ты источаешь благоухание мира всем, с верой приходящим к раке с мощами твоими, Ефрем преподобный. Поэтому мы взываем к тебе: «Слава Давшему тебе благодать чудотворений, слава Прославившему тебя чудесами, слава Подающему через тебя всем исцеления»."},
  {"id": "ru-mol-0356", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0357", "section": "service", "who": "rubric", "text": "Ефрему Перекопскому, Новгородскому чдтв.,"},
  {"id": "ru-mol-0358", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0359", "section": "service", "who": "reader", "text": "Перевод: С юности твоей всецело покорился Богу, блаженный, и ради Его любви Отечество и родственников ты оставил, поселился в пустыни, в ней же, явив суровую жизнь, ты принял дарование чудес от Бога, преподобный Ефрем. Моли Христа Бога да спасет души наши."},
  {"id": "ru-mol-0360", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0361", "section": "service", "who": "rubric", "text": "Ефрему Печерскому, еп. Переяславскому,"},
  {"id": "ru-mol-0362", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0363", "section": "service", "who": "reader", "text": "Перевод: Горя духом путешествий к святым местам, ты странствовал в Греческую землю, святитель Ефрем, откуда со многой пользой вернулся, переписав устав святого Студийского монастыря, как достойный великого уважения дар принес его, им же по сей день управляемая Церковь Российская славит тебя, истинного о ней попечителя."},
  {"id": "ru-mol-0364", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0365", "section": "service", "who": "rubric", "text": "Ефрему Сирину,"},
  {"id": "ru-mol-0366", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0367", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню и стенаниями из глубины плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Ефрем, отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0368", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0369", "section": "service", "who": "rubric", "text": "Захарии, постнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0370", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0371", "section": "service", "who": "reader", "text": "Перевод: Как следствие твоей постнической жизни, блаженный Захария, ты получил великую силу над бесами, молись, чтобы и нам избавиться от их козней, получить прощение грехов и великую милость."},
  {"id": "ru-mol-0372", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0373", "section": "service", "who": "rubric", "text": "Зинону, постнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0374", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0375", "section": "service", "who": "reader", "text": "Перевод: Преподобный отче Зинон, благочестивую и святую жизнь на земле проводивший и тем Богу весьма угодивший, моли о нас, почитающих память твою."},
  {"id": "ru-mol-0376", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0377", "section": "service", "who": "rubric", "text": "Зосиме, игумену Соловецкому,"},
  {"id": "ru-mol-0378", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0379", "section": "service", "who": "reader", "text": "Перевод: По воле Божественного разума ты поселился в пустыни и там, устремив ум свой к Небесным обителям, прожил на земле жизнь, подобную ангельской, в молитвах, трудах и пощении примером был твоим ученикам. Потому Бог, видя твое благое устремление, увеличил число твоих учеников в пустыни, орошаемой потоками слез твоих. Но, как имеющий дерзновение к Богу, вспоминай стадо, которое собрал ты, мудрый, и не забудь как обещал посещать чад твоих, Зосима преподобный, отче наш."},
  {"id": "ru-mol-0380", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0381", "section": "service", "who": "rubric", "text": "Зосиме и Савватию Соловецким,"},
  {"id": "ru-mol-0382", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0383", "section": "service", "who": "reader", "text": "Перевод: Постнической и подобной ангельской жизнью вашей, преподобные отцы Зосима и Савватий, по всей земле вы стали известны; различными чудотворениями, Богоносные, просвещаете с верой призывающих вас и почитающих священную память вашу."},
  {"id": "ru-mol-0384", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0385", "section": "service", "who": "rubric", "text": "Тем же святым, на перенесение мощей,"},
  {"id": "ru-mol-0386", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0387", "section": "service", "who": "reader", "text": "Перевод: Как светильники явились преяркие на морском острове, преподобные отцы Зосима и Савватий, ибо вы, взяв крест Христов на плечи, усердно последовали за Ним и, приблизившись чистотой к Богу, обогатились силой чудотворений. Потому и мы с любовью приходим к ракам с почитаемыми мощами вашими и с благоговением говорим: «О преподобные, молите Христа Бога о спасении душ наших»."},
  {"id": "ru-mol-0388", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0389", "section": "service", "who": "rubric", "text": "Иакову Железноборовскому,"},
  {"id": "ru-mol-0390", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0391", "section": "service", "who": "reader", "text": "Перевод: Желая Небесного, ты отвратился от всего земного и, взяв крест свой, последовал за Христом и от Него принял дар чудотворений, исцеления больных. Но, как имеющий право обращаться ко Святой Троице, испроси для православных христиан здоровье и спасение, победу над врагами и не оставь детей своих, обращая внимание на всех, припадающих к подающему исцеления гробу твоему, Иаков, преподобный отче наш."},
  {"id": "ru-mol-0392", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0393", "section": "service", "who": "rubric", "text": "Игнатию, архим. Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0394", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0395", "section": "service", "who": "reader", "text": "Перевод: Благодаря чистой и непорочной твоей жизни, Богоносный отче Игнатий, получивший от Господа чудотворные дары исцелять больных, исцели, молим тебя, и немощи наши, моля о нас Единого Человеколюбца."},
  {"id": "ru-mol-0396", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0397", "section": "service", "who": "rubric", "text": "Илариону Великому,"},
  {"id": "ru-mol-0398", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0399", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню, и стенаниями из глубины плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Иларион, отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0400", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0401", "section": "service", "who": "rubric", "text": "Илариону Псковоезерскому, Гдовскому,"},
  {"id": "ru-mol-0402", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0403", "section": "service", "who": "reader", "text": "Перевод: Бодрствуя в молитвах, ты был пресветлым храмом Духа Святого, потому и стал преудивительным чудотворцем, преподобный отче наш Иларион. Моли о нас Христа Бога просветить нас светом Божественного познания и спасти души наши."},
  {"id": "ru-mol-0404", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0405", "section": "service", "who": "rubric", "text": "Илариону, схимнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0406", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0407", "section": "service", "who": "reader", "text": "Перевод: Воистину по достоинству ты назван был Иларион (от греч. Iλαρίων — тихий), поскольку имел тихий и кроткий нрав согласно с именем твоим, блаженный, тем самым угодив кроткому Господу Иисусу, молись Ему о нас, рабах твоих."},
  {"id": "ru-mol-0408", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0409", "section": "service", "who": "rubric", "text": "Иннокентию Комельскому, Вологодскому,"},
  {"id": "ru-mol-0410", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0411", "section": "service", "who": "reader", "text": "Перевод: С юности ты был избранным сосудом (Деян.9:15) и в жизни послужил Богу, учитель монахов Иннокентий, ты старался худшее подчинить лучшему, потому, умертвив страсти, ты возвысился к видению несозданной (нетварной) красоты у Бога, перед Которым ты предстоишь. Моли, отец, Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0412", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0413", "section": "service", "who": "rubric", "text": "Иоакиму Сарандопорскому, Осоговскому,"},
  {"id": "ru-mol-0414", "section": "service", "who": "rubric", "text": "глас 7"},
  {"id": "ru-mol-0415", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0416", "section": "service", "who": "rubric", "text": "Иоанну Дамаскину,"},
  {"id": "ru-mol-0417", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0418", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и чистоты, светильник вселенной, монашествующих Богодухновенное украшение, Иоанн премудрый, учениями твоими ты всех просветил, лира духовная; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0419", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0420", "section": "service", "who": "rubric", "text": "Иоанну, затворнику Святогорскому,"},
  {"id": "ru-mol-0421", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0422", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0423", "section": "service", "who": "rubric", "text": "Иоанну Лествичнику,"},
  {"id": "ru-mol-0424", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0425", "section": "service", "who": "reader", "text": "Перевод: Как Божественную лестницу, обрели мы, Иоанн преподобный, твои Божественные добродетели, к Небесам возводящие нас, ибо ты был образцом добродетелей. Потому моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0426", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0427", "section": "service", "who": "rubric", "text": "Иоанну Многострадальному, Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0428", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0429", "section": "service", "who": "reader", "text": "Перевод: Терпения крепость истинно непоколебимая и несокрушимая стена от вражеских стрел, равный ангелам и многострадальный отче наш Иоанн, почитая тебя, мы, недостойные, горячо молимся, припадая к драгоценным мощам твоими, избавь нас растлевающих душу страстей телесных и спаси твоими молитвами."},
  {"id": "ru-mol-0430", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0431", "section": "service", "who": "rubric", "text": "Иоанну Пещернику (иже в странах Вавилонских),"},
  {"id": "ru-mol-0432", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0433", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0434", "section": "service", "who": "rubric", "text": "Иоанну Рыльскому,"},
  {"id": "ru-mol-0435", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0436", "section": "service", "who": "reader", "text": "Перевод: Покаяния основанием, смирения изложением, примером утешающим, духовно совершенной, подобной ангельской жизнь твоя была, преподобный. В молитвах, пощении и в слезах пребывавший, отче Иоанн, моли Христа Бога о душах наших."},
  {"id": "ru-mol-0437", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0438", "section": "service", "who": "rubric", "text": "Тому же святому, на возвращение мощей из Терново в Рыльский монастырь,"},
  {"id": "ru-mol-0439", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0440", "section": "service", "who": "reader", "text": "Перевод: Возвращением твоих мощей обитель твоя обогатилась, церковь же твоя, приняв их, просветилась и, украсившись, созывает верующих светло и радостно праздновать светоносный день твоей памяти, придите, взывая, и получите дары благодати."},
  {"id": "ru-mol-0441", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0442", "section": "service", "who": "rubric", "text": "Иоанну Яренгскому,"},
  {"id": "ru-mol-0443", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0444", "section": "service", "who": "reader", "text": "Перевод: От земли Возведший тебя в вечные обители, сохраняет и после смерти невредимым тело твое, святой Иоанн, ибо ты в целомудрии и чистоте жития, блаженный, провел жизнь, не осквернив тело, потому с дерзновением моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0445", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0446", "section": "service", "who": "rubric", "text": "Иоанну и Лонгину Яренгским, на перенесение мощей,"},
  {"id": "ru-mol-0447", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0448", "section": "service", "who": "reader", "text": "Перевод: Как звезды яркие, с юности воссиявшие, вы осветили сердца верующих перенесением почитаемых мощей ваших, добродетелями чудес ваших вы явились на земле, как ангелы во плоти, насаждены были пощением, как дерево у источника вод воздержания (Пс.1:3), напоенные потоками слез ваших, вы омыли нечистоту, потому стали вместилищами Духа Божия, Иоанн и Лонгин, молите Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0449", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0450", "section": "service", "who": "rubric", "text": "Иоанникию Великому,"},
  {"id": "ru-mol-0451", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0452", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню, и из глубины стенаниями плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Иоанникий, отче наш; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0453", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0454", "section": "service", "who": "rubric", "text": "Иоанникию Девиченскому, Сербскому,"},
  {"id": "ru-mol-0455", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0456", "section": "service", "who": "reader", "text": "Перевод: Пощением, молитвой и благодатью Божественной просветившись, ты ярко озаряешь концы земли, с благоговением приняв благодать чудотворений от Бога, исцеляешь болезни, духов же бесовских отгоняешь от людей, прибегающих с верой к раке с твоими святыми мощами, преподобный отче наш Иоанникий. Слава Давшему тебе благодать, слава Укрепившему тебя, слава Подающему через тебя всем исцеления."},
  {"id": "ru-mol-0457", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0458", "section": "service", "who": "rubric", "text": "Иоасафу, царевичу Индийскому,"},
  {"id": "ru-mol-0459", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0460", "section": "service", "who": "reader", "text": "Перевод: От материнского чрева ты был прекрасным вместилищем Святого Духа, преславный Иоасаф, и от блаженного Варлаама бесценное сокровище, Христа, в сердце свое принял, и Божественным Крещением Индию просветил ты, беззаконие предков исправив, привел ты всех от тьмы к свету Богоразумия и, оставив тленное земное царство, достиг пустыни и своего учителя, потому на Небесах от Живоначальной Троицы венцом царским увенчался, моли о нас, почитающих священную память твою."},
  {"id": "ru-mol-0461", "section": "service", "who": "rubric", "text": "Величание"},
  {"id": "ru-mol-0462", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0463", "section": "service", "who": "rubric", "text": "Иоасафу Каменскому, Спасокубенскому, Вологодскому чдтв.,"},
  {"id": "ru-mol-0464", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0465", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0466", "section": "service", "who": "rubric", "text": "Иоасафу Метеорскому,"},
  {"id": "ru-mol-0467", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0468", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0469", "section": "service", "who": "rubric", "text": "Иову, игумену Почаевскому,"},
  {"id": "ru-mol-0470", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0471", "section": "service", "who": "reader", "text": "Перевод: Возложив на себя иго Христово с юности (Мф.11:29-30), преподобный отче Иов, многие годы ты свято подвизался на поприще благочестия в Угорницкой обители и на острове Дубенском и, прийдя к горе Почаевской, ознаменовавшейся исцеляющей стопой Пресвятой Богородицы, в тесной пещере каменной, ради богомыслия и молитвы ты многократно закрывался и, благодатью Божией укрепляясь, мужественно потрудился ты на пользу Церкви Христовой и обители твоей, а также против врагов Православия и благочестия христианского и, обучая тому же ряды монашествующих, ты привел их как победителей Владыке и Богу. Его моли о спасении наших душ."},
  {"id": "ru-mol-0472", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0473", "section": "service", "who": "rubric", "text": "Ионе Клименецкому, Олонецкому,"},
  {"id": "ru-mol-0474", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0475", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0476", "section": "service", "who": "rubric", "text": "Иосифу, игумену Волоцкому, чдтв.,"},
  {"id": "ru-mol-0477", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0478", "section": "service", "who": "reader", "text": "Перевод: Как украшение постников и отцов красоту, милости подателя, рассуждения светильника, все верующие собравшись прославим, кротости учителя, ереси посрамившего, Российскую звезду, премудрого Иосифа, молящегося Господу о помиловании душ наших."},
  {"id": "ru-mol-0479", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0480", "section": "service", "who": "rubric", "text": "Иосифу Заоникиевскому,"},
  {"id": "ru-mol-0481", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0482", "section": "service", "who": "reader", "text": "Перевод: С самого начала святое житие твое, преподобный, мудростью юродства от людей утаенное, было известно ангелам на Небесах, и хотя на земле ты жил в беспомощности из-за болезни глаз, но на духовных крыльях ты взлетел на высоту, осиянный вечным светом, получив Небесное Отечество в наследство. В земных, считающихся красивыми домах ты не нуждался, но в Небесных селениях светлое жилище ты обрел. Ты не одевался в мягкие одежды, но больше полюбил власяницу и потому обрел ты не земные блага, а Небесные сокровища. Живя во плоти на земле, ты был един с бесплотными ангелами, служа Небесной Царице и наслаждаясь воспеваемыми для Нее ангельскими песнопениями, которые многие люди хотели бы услышать, но не могут насладиться ими. Поэтому Всевышний Творец образ Свой и родившей Его Богоматери с высоты небесной в руки твои, как на крылья херувимов, передал, и от этого образа вечным светом просветил твои глаза, и, как из облака дождевого, молитвами твоими весь мир напоил и сейчас, в последние времена, святые мощи твои, как Эдемский источник, для исцеления болезней нам устроил. Его же моли, наставник наш, чудотворец Иосиф, даровать нам мир и великую милость."},
  {"id": "ru-mol-0483", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0484", "section": "service", "who": "rubric", "text": "Иосифу Многоболезненному, Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0485", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0486", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню и стенаниями из глубины плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Иосиф, отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0487", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0488", "section": "service", "who": "rubric", "text": "Ипатию целебнику, Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0489", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0490", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0491", "section": "service", "who": "rubric", "text": "Иринарху, затворнику Ростовскому,"},
  {"id": "ru-mol-0492", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0493", "section": "service", "who": "reader", "text": "Перевод: Как мученика добровольного и преподобных украшение, звезду Ростовскую, в затворе, цепях и веригах Господу угодившего и чудес благодать от Него получившего, Иринарха удивительного в хвалебных песнопениях почтим и коленопреклоненно в сокрушении к нему воззовем: «Отче преподобный, моли Христа Бога о спасении душ наших»."},
  {"id": "ru-mol-0494", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0495", "section": "service", "who": "rubric", "text": "Иринарху Соловецкому,"},
  {"id": "ru-mol-0496", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0497", "section": "service", "who": "reader", "text": "Перевод: Постническое в Боге житие возлюбив, все плотские мудрования покорил ты духу и умертвил воздержанием страсти, в трудах, бдениях и молитвах был примером добродетели, этим став наставником монашеского жития, отче преподобный Иринарх. Моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0498", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0499", "section": "service", "who": "rubric", "text": "Иродиону Илоезерскому,"},
  {"id": "ru-mol-0500", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0501", "section": "service", "who": "reader", "text": "Перевод: Просияв сегодня ярко, радуется город Белозерск, имеющий в своей области великого светильника, блаженного отца Иродиона, который процвел, как пальма, насажденная в доме Божией Матери, как кедр, выросший у источников благодати Христовой, как благоуханная роза, огражденный от бедствий водами. Собравшись люди празднуют пресветлую память его, осиянные многими благодеяниями и чудесами: просящим с верой исцеления, страдающим от различных болезней подает здоровье. И мы, как чада твои, коленопреклоненно молимся тебе: «Моли Пресвятую Троицу о том, чтобы сохраниться городу нашему от нашествия иноплеменников и от врагов видимых и невидимых. Так как мы, отче, спасаемые твоими молитвами ко Господу всегда просим с верой у тебя: моли о нас Христа Бога о спасении душ наших»."},
  {"id": "ru-mol-0502", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0503", "section": "service", "who": "rubric", "text": "Исаакию, затворнику Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0504", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0505", "section": "service", "who": "reader", "text": "Перевод: Светлости святых насладится пожелав, в темной поселился ты пещере, прославляемый, и отлично подвизался ты, Исаакий, обманут был врагом, но разрушил все его коварство. И сейчас, как победитель, с радостью предстоя Христу Богу, испроси нам мир и великую милость."},
  {"id": "ru-mol-0506", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0507", "section": "service", "who": "rubric", "text": "Тропарь преподобному Иустину (Поповичу) Челийскому,"},
  {"id": "ru-mol-0508", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0509", "section": "service", "who": "reader", "text": "Перевод: Православия сладость, нектар премудрости, отче преподобный, излил ты в сердца верующих как богатство: житием своим и учением ты явился живой книгой Духа, Иустин Богомудрый, моли Христа Бога Логоса, да ологосит почитающих тебя."},
  {"id": "ru-mol-0510", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0511", "section": "service", "who": "rubric", "text": "Кассиану Греку, Угличскому чдтв.,"},
  {"id": "ru-mol-0512", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0513", "section": "service", "who": "reader", "text": "Перевод: Воспитанный древним Римом, столицу отечества твоего, город Мангуп, ради Христа ты оставил, и княжением и недолговечной славой этой суетной жизни ты пренебрег, и земному богатству ты предпочел Небесное богатство и вечную славу, возвысив ум свой к Богу, и стремился жить подобно Ангелам, направляемый промыслом Божественного разума, и дошел до спасемого Богом города Углича, и близко, в пределах его, над рекой Волгой, поселился в пустыни, и воздвиг преславную обитель в честь Божией Матери, и в ней тело свое предал Богу, как освященный дар. Потому молим тебя, отче Кассиан, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0514", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0515", "section": "service", "who": "rubric", "text": "Кассиану послушнику и постнику, Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0516", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0517", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0518", "section": "service", "who": "rubric", "text": "Кассиану Римлянину,"},
  {"id": "ru-mol-0519", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0520", "section": "service", "who": "reader", "text": "Перевод: Предварительно очистившись постом, ты достиг познания мудрости. От Богоносных отцов, живущих в пустыне, ты научился сдерживанию страстей. Поэтому подай нам твоими молитвами послушание нашего тела нашему духу, потому что ты учитель, преподобный Кассиан, всех воспевающих во Христе твою память."},
  {"id": "ru-mol-0521", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0522", "section": "service", "who": "rubric", "text": "Кириаку отшельнику,"},
  {"id": "ru-mol-0523", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0524", "section": "service", "who": "reader", "text": "Перевод: Пустынным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Кириак: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-0525", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0526", "section": "service", "who": "rubric", "text": "Кириллу, игумену Белоезерскому,"},
  {"id": "ru-mol-0527", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0528", "section": "service", "who": "reader", "text": "Перевод: Как лилия в пустыни, по Писанию, расцвел ты, отче Кирилл, терние порочных страстей искореняя, и собрал в ней множество учеников, направляемых страхом Божиим и учением твоим, их же до конца, как любящий своих детей отец, ты не оставил, оказывая им внимание, да все взываем к тебе: «Слава Давшему тебе силу, слава Венчавшему тебя, слава Подающему через тебя всем исцеления»."},
  {"id": "ru-mol-0529", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0530", "section": "service", "who": "rubric", "text": "Кириллу Новоезерскому,"},
  {"id": "ru-mol-0531", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0532", "section": "service", "who": "reader", "text": "Перевод: Руководимый Божиим духом, слез твоих ливнями ты напоил все иссохшее и явил бесплотное житие в пустыни, благодетельными трудами — неусыпными молитвами из глубины сердца и постом — ты уплодоносил ее и всю вселенную просветил сиянием чудес твоих, отче наш Кирилл. Моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0533", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0534", "section": "service", "who": "rubric", "text": "Тому же святому, на обретение мощей,"},
  {"id": "ru-mol-0535", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0536", "section": "service", "who": "reader", "text": "Перевод: Как светильник яркий явился ты на Красном острове Нового озера, преподобный отче Кирилл, ибо ты, крест Христов подняв на плечи, усердно Ему последовал, чистотою к Богу приблизившись, от Него же и обогатился силой чудотворений, потому и мы с любовью приходим к раке с почитаемыми мощами твоими, смиренно взывая: «О преподобный отче Кирилл, моли Христа Бога о спасении душ наших»."},
  {"id": "ru-mol-0537", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0538", "section": "service", "who": "rubric", "text": "Кириллу Челмогорскому,"},
  {"id": "ru-mol-0539", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0540", "section": "service", "who": "reader", "text": "Перевод: Сегодня воссияла нам преяркая память твоя, прославляемый, как солнце светозарное, лучами благодати озаряющее весь мир и ночную тьму злых духов от нас отгоняющее. Сегодня Небесные силы святых ангелов и все народы земли, и души праведных духовно торжествуют, радуясь, сегодня и мы, грешные, коленопреклоненно молимся: «Отче преподобный Кирилл, Христа Бога моли непрестанно о спасении обители твоей, города и людей, с любовью тебя почитающих»."},
  {"id": "ru-mol-0541", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0542", "section": "service", "who": "rubric", "text": "Кириллу и Марии, схимм. Радонежским,"},
  {"id": "ru-mol-0543", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0544", "section": "service", "who": "reader", "text": "Перевод: Блаженств Христовых причастники, почитаемого супружества и заботы о детях прекрасный пример, праведные Кирилл и Мария, плод благочестия, Сергия преподобного, нам явившие, с ним же усердно молите Господа ниспослать нам дух любви и смиренномудрия, да в мире и единомыслии прославим Троицу Единосущную."},
  {"id": "ru-mol-0545", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0546", "section": "service", "who": "rubric", "text": "Константину и Косме Косинским, Старорусским,"},
  {"id": "ru-mol-0547", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0548", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0549", "section": "service", "who": "rubric", "text": "Корнилию, чдтв. Комельскому,"},
  {"id": "ru-mol-0550", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0551", "section": "service", "who": "reader", "text": "Перевод: С юности воспламеняем горячим стремлением к Божественной любви, ты оставил житейскую суету, преподобный, став ревнителем Антонию Великому, безмолвием и суровой жизнью последуя Христу, в бдении, молитвах и посте ты был примером для своих учеников. Потому молись Господу, блаженный Корнилий, о спасении наших душ."},
  {"id": "ru-mol-0552", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0553", "section": "service", "who": "rubric", "text": "Корнилию, игумену Палеостровскому, Олонецкому,"},
  {"id": "ru-mol-0554", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0555", "section": "service", "who": "reader", "text": "Перевод: С юности, премудрый, ты настойчиво подвизался, наставляемый Богом, оставил отечество твое — город Псков — и поселился в пустыни, на острове великого Онежского озера, с мудростью собрав монахов и основав обитель по благословению Святого Духа и создав храм Пресвятой Богородицы, в честь Рождества Ее. Потоками же слез твоих ты потопил бесплотных врагов и целомудрием твоей жизни соединился с собранием ангельским, преподобный отче Корнилий, с ними же Христа Бога моли о спасении наших душ."},
  {"id": "ru-mol-0556", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0557", "section": "service", "who": "rubric", "text": "Корнилию Переяславскому,"},
  {"id": "ru-mol-0558", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0559", "section": "service", "who": "reader", "text": "Перевод: Новоявленного нам угодника Божия почтим, Корнилия преподобного, крест на плечи поднявшего, иго Христово с усердием понесшего, против невидимых врагов мужественно подвизавшегося и козни их сокрушившего, как хороший воин он предстал Владыке Христу и молится не переставая о душах наших."},
  {"id": "ru-mol-0560", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0561", "section": "service", "who": "rubric", "text": "Косме, епископу Маиумскому,"},
  {"id": "ru-mol-0562", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0563", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и чистоты, вселенной светильник, архиереев Богодухновенное украшение, Косма премудрый, учениями твоими всех просветил ты, лира духовная, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0564", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0565", "section": "service", "who": "rubric", "text": "Косме Яхромскому,"},
  {"id": "ru-mol-0566", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0567", "section": "service", "who": "reader", "text": "Перевод: Небесной желая надмирной жизни, земное возненавидел ты и, взяв крест свой, последовал ты Христу и в пустыни поселился ты, достойный удивления, в ней подвизался в пении, бдении и пощении. Потому вселился в тебя Пресвятой Дух, но как имеющий дерзновение ко Христу Богу, испроси людям православным здоровье и спасение, и не забывай оказывать милость к чадам своим, празднующим священную память твою, Косма, преподобный отче наш."},
  {"id": "ru-mol-0568", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0569", "section": "service", "who": "rubric", "text": "Ксенофонту Робейскому,"},
  {"id": "ru-mol-0570", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0571", "section": "service", "who": "reader", "text": "Перевод: Ты стал прекрасным произрастанием пустыни, отче преподобный, ибо с юности ты предпочел чистую жизнь, духовному учителю последуя, и, его наставлением ум свой к Небесному устремив, поселился в пустыни и в ней создал монастырь, и для стада своего стал премудрым наставником, Великому же Новгороду честью и силой, потому и Христос, как преяркого светильника, обогатил тебя чудесами и прославил тебя, Ксенофонт, отче наш, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0572", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0573", "section": "service", "who": "rubric", "text": "Кукше Новому, Одесскому,"},
  {"id": "ru-mol-0574", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0575", "section": "service", "who": "reader", "text": "Перевод: С юности мир суемудрый и лукавый оставил ты, Божественною свыше просветившись благодатью, преподобный, со многим терпением во временной жизни подвиг совершил ты, потому источаешь благодать чудес всем с верой приходящим к раке с мощами твоими, Кукша, преблаженный отче наш."},
  {"id": "ru-mol-0576", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0577", "section": "service", "who": "rubric", "text": "Кукше, сщмч. и Пимену постнику, Печерским, в Ближних пещерах,"},
  {"id": "ru-mol-0578", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0579", "section": "service", "who": "reader", "text": "Перевод: Мученической кровью, иеромонах Кукша, в проповеди Евангелия с учеником твоим блаженным Никоном, с честью украсившийся, и Пимен в постничестве светозарно просиявший, в один день и час вошли вы в свет неприступный, где молитесь Господу, да подаст нам великую милость."},
  {"id": "ru-mol-0580", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0581", "section": "service", "who": "rubric", "text": "Лаврентию, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0582", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0583", "section": "service", "who": "reader", "text": "Перевод: Затворивший себя на многие годы Господа ради в темной пещере, преподобный отче Лаврентий, и Ему прекрасно в ней угодивший, подай и нам от всякого зла закрыть свои чувства, и тьмы страстей отвратиться, и светлость получить Царства Небесного."},
  {"id": "ru-mol-0584", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0585", "section": "service", "who": "rubric", "text": "Лаврентию, затворнику Печерскому, епископу Туровскому, в Ближних пещерах,"},
  {"id": "ru-mol-0586", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0587", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0588", "section": "service", "who": "rubric", "text": "Лаврентию Черниговскому,"},
  {"id": "ru-mol-0589", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0590", "section": "service", "who": "reader", "text": "Перевод: С юности Христа возлюбил ты и Ему тесным путем последуя (Мф.7:13-14), стал избранным сосудом Духа Святого (2Тим.2:21), получив дар чудотворения и прозорливости, потому в незаходящем свете Пресвятой Троицы всегда радуясь, вспоминай чад твоих, Лаврентий преподобный, отче наш."},
  {"id": "ru-mol-0591", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0592", "section": "service", "who": "rubric", "text": "Лазарю Галисийскому,"},
  {"id": "ru-mol-0593", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0594", "section": "service", "who": "reader", "text": "Перевод: Неутомимыми молитвами, потоками слез ты столп омочил, и из глубины стенаниями плод трудов своих умножил во сто крат, и был пастырем, всем подающим прощение, преподобный отче наш Лазарь, молись Христу Богу о спасении душ наших."},
  {"id": "ru-mol-0595", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0596", "section": "service", "who": "rubric", "text": "Леониду Устьнедумскому,"},
  {"id": "ru-mol-0597", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0598", "section": "service", "who": "reader", "text": "Перевод: Божественной любовью и духовным житием с юности воспламенился, преподобный, и все мирские блага возненавидев, Христа одного от души возлюбил ты, отче, легкое иго на плечи взяв (Мф.11:29-30), Божественным Промыслом и чудесным явлением Богородицы направляемый достиг пустыни и в ней долгие годы подвизался ты во многих трудах и слезах, терпением всяких напастей плоть свою изнуряя. Потому Бог, видя твои труды, увеличил чада твои в пустыни. Но, как имеющий дерзновение к Богу, моли о нас, рабах твоих, отче преподобный Леонид, да избавит нас от всех козней вражеских и спасет души наши."},
  {"id": "ru-mol-0599", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0600", "section": "service", "who": "rubric", "text": "Леонтию, канонарху Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0601", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0602", "section": "service", "who": "reader", "text": "Перевод: Достойный особого почитания канонарх Леонтий, первым возглашавший правило (греч. κᾰνών = правило, канон) в церкви и в монашеском правиле воссиявший ярко, моли Христа Бога, чтобы Он подал душам нашим отпущение прегрешений."},
  {"id": "ru-mol-0603", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0604", "section": "service", "who": "rubric", "text": "Лонгину Коряжемскому,"},
  {"id": "ru-mol-0605", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0606", "section": "service", "who": "reader", "text": "Перевод: От суеты мирской удалившись, к немеркнущему Свету пришел ты, преподобный отче Лонгин, и сейчас ясно созерцаешь Святую Троицу, Ее же моли о нас недостойных, да спасет души наши."},
  {"id": "ru-mol-0607", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0608", "section": "service", "who": "rubric", "text": "Лонгину, вратарю Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0609", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0610", "section": "service", "who": "reader", "text": "Перевод: Преподобный и Богоблаженный отче Лонгин, врат монастырских бдительный стражник, бдительнейший же и неутомимый своих чувств от всякой мирской суеты страж, моли назвавшего Себя дверью (Ин.10:7) Господа Славы, да откроет нам дверь милости Своей."},
  {"id": "ru-mol-0611", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0612", "section": "service", "who": "rubric", "text": "Лонгину Яренгскому,"},
  {"id": "ru-mol-0613", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0614", "section": "service", "who": "reader", "text": "Перевод: Просветившись свыше Божественной благодатью, Богомудрый, со многим терпением ты совершил путь временной жизни, потому и после успения источаешь благодать чудес всем, с верой приходящим к тебе, Лонгин всеблаженный. Слава Давшему тебе силу, слава Прославившему тебя чудесами, слава Подающему через тебя всем исцеления."},
  {"id": "ru-mol-0615", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0616", "section": "service", "who": "rubric", "text": "Макарию Великому, Египетскому,"},
  {"id": "ru-mol-0617", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0618", "section": "service", "who": "reader", "text": "Перевод: Пустынным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Макарий: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-0619", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0620", "section": "service", "who": "rubric", "text": "Макарию Жабынскому, Белевскому чдтв.,"},
  {"id": "ru-mol-0621", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0622", "section": "service", "who": "reader", "text": "Перевод: От мирской жизни удалившись в тихое пристанище монашеского жития, преподобный Макарий, ты прекрасно подвизался в нем, душу твою добродетелями высочайшими обогатил и стал добрым пастырем и учителем собранию монахов, для которых ты и создал обитель, в ней же, обретя безмолвие и удостоившись видения Бога, ко Господу ты преставился, Который обогатил тебя даром чудотворений. Его же сейчас моли, да спасет всех с верой и любовью почитающих святую память твою."},
  {"id": "ru-mol-0623", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0624", "section": "service", "who": "rubric", "text": "Макарию Желтоводскому, Унженскому,"},
  {"id": "ru-mol-0625", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0626", "section": "service", "who": "reader", "text": "Перевод: Сегодня город твой Галич тобой гордится, ибо в его пределах преярко, как великое солнце, воссиял ты и чудесами твоими, преподобный Макарий, все озарил. И сейчас молись Господу об избавлении наших душ от обольщения вражеского и о спасении города твоего от языческого нашествия."},
  {"id": "ru-mol-0627", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0628", "section": "service", "who": "rubric", "text": "Макарию, игумену Калязинскому, чдтв.,"},
  {"id": "ru-mol-0629", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0630", "section": "service", "who": "reader", "text": "Перевод: Помышления плотские, отец Макарий, воздержанием и бдением ты умертвил, место же, на котором ты проливал свой пот, как труба взывает к Богу, повествуя о твоих подвигах, и после смерти чтимые твои мощи источают исцеления. Потому восклицаем тебе: моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0631", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0632", "section": "service", "who": "rubric", "text": "Макарию Оредежскому, Новгородскому,"},
  {"id": "ru-mol-0633", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0634", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0635", "section": "service", "who": "rubric", "text": "Макарию, диакону Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0636", "section": "service", "who": "rubric", "text": "глас 7"},
  {"id": "ru-mol-0637", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0638", "section": "service", "who": "rubric", "text": "Макарию, постнику Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0639", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0640", "section": "service", "who": "reader", "text": "Перевод: Ты был нестяжателем Христа ради и Он за многие твои добродетели в сердце твоем поселился, блаженный Макарий, молись о нас, воспевающих тебя."},
  {"id": "ru-mol-0641", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0642", "section": "service", "who": "rubric", "text": "Макарию Римлянину, Новгородскому чдтв.,"},
  {"id": "ru-mol-0643", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0644", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0645", "section": "service", "who": "rubric", "text": "Макрине,"},
  {"id": "ru-mol-0646", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0647", "section": "service", "who": "reader", "text": "Перевод: Жениха твоего (Христа) смерть видевшая, рассмотрела тленность жизни и суету мирскую, отовсюду получив достаточные основания, Нетленному Обручнику ты стала невестой, постом и смирением постигая Его любовь. Потому сейчас радуется с Ангелами, преподобная Макрина, дух твой."},
  {"id": "ru-mol-0648", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0649", "section": "service", "who": "rubric", "text": "Максиму Греку,"},
  {"id": "ru-mol-0650", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0651", "section": "service", "who": "reader", "text": "Перевод: Сиянием Духа озаряем, ты от Божией Премудрости удостоился искусства красноречия, неведением омраченные сердца людей светом благочестия просвещая, явился пресветлым Православия светильником, Максим преподобный. Потому, ревнуя о Всевидящем, ты, лишенный отечества и странник, в Российской стране жил как пришелец. Страдания в темницах и заточение от самодержца претерпев, ты десницею Всевышнего венчаешься и чудодействуешь преславно. Будь и о нас ходатаем неизменным, почитающих с любовью святую память твою."},
  {"id": "ru-mol-0652", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0653", "section": "service", "who": "rubric", "text": "Максиму Исповеднику,"},
  {"id": "ru-mol-0654", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0655", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и чистоты, светильник вселенной, архиереев Богодухновенное украшение, Максим премудрый, учениями твоими ты всех просветил, лира духовная; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0656", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0657", "section": "service", "who": "rubric", "text": "Мардарию, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0658", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0659", "section": "service", "who": "reader", "text": "Перевод: Ты был, блаженный Мардарий, нестяжателем Христа ради, и Он за многие твои благодеяния поселился в сердце твоем. Молись о нас, воспевающих тебя."},
  {"id": "ru-mol-0660", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0661", "section": "service", "who": "rubric", "text": "Марку Гробокопателю, Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0662", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0663", "section": "service", "who": "reader", "text": "Перевод: Умертвив плотские похоти многим воздержанием и копанием могил для святых, всегда проживая в пещере, как мертвый, повелением своим мертвых поднимал ты, Марк прославляемый, умертви и наши мудрования плотские и направь нас на путь добродетелей, моля о нас Единого Человеколюбца."},
  {"id": "ru-mol-0664", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0665", "section": "service", "who": "rubric", "text": "Марку, Ионе и Корнилию Псково-Печерским,"},
  {"id": "ru-mol-0666", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0667", "section": "service", "who": "reader", "text": "Перевод: Как светильники явились преяркие в пещерах Царицы Богоматери (в пещерах Свято-Успенского Псково-Печерского монастыря), преподобные отцы наши Марк, Иона и Корнилий, потому что вы, подняв крест Христов на свои плечи, смело последовали за Ним и приблизились в чистоте к Богу, от Того и обогатились силой чудотворений. Поэтому и мы с усердием прибегаем к вам и сокрушенно взываем: «О преподобные, молите Христа Бога о спасении душ наших»."},
  {"id": "ru-mol-0668", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0669", "section": "service", "who": "rubric", "text": "Марону, пустыннику Сирийскому,"},
  {"id": "ru-mol-0670", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0671", "section": "service", "who": "reader", "text": "Перевод: Незакатное солнце воссияло нам сегодня в твоих светоносных молитвах, преподобный отче наш Марон, дошедший до одной горы и почитаемый живущими там язычниками за высоту твоей добродетели у Бога, и там, найдя идольское капище, ты освятил его и пребывал в нем. Человеколюбец Бог, видевший твои труды и подвиг, вручил тебе дар Свой, сделавший тебя известным, исцелять боль, горячку и лихорадку приходящих к тебе с верой. Потому взываем к тебе: «Радуйся целитель наш быстрый, радуйся защитник наш горячий, ибо предстоишь у Пресвятой Троицы, молись Ей о призывающих святое имя твое, да избавит от этих тяжелых болезней и спасет души наши»."},
  {"id": "ru-mol-0672", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0673", "section": "service", "who": "rubric", "text": "Мартину Туровскому,"},
  {"id": "ru-mol-0674", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0675", "section": "service", "who": "reader", "text": "Перевод: Тяжелой болезнью страдающий и людьми забытый, молил ты об утолении жажды, преподобный Мартин, потому Христос послал с Небес благоверных Бориса и Глеба — послужить тебе и исцелить болезнь."},
  {"id": "ru-mol-0676", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0677", "section": "service", "who": "rubric", "text": "Мартиниану Белоезерскому,"},
  {"id": "ru-mol-0678", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0679", "section": "service", "who": "reader", "text": "Перевод: Бог с юности, отче, избравший и возлюбивший тебя, и предвидящий твою добрую волю, научил тебя прийти к преподобному Своему угоднику Кириллу всеблаженному, который направил тебя на путь спасения, в страхе Божием и чистоте душевной, в благоговении и непрестанных к Богу молитвах жизненный путь свой ты прошел непорочно, став удивительным пастырем и наставником монахов, и сейчас, с дерзновением предстоя на Небесах Престолу Христову, с ангелами светло торжествуя, отче преподобный, Мартиниан всеблаженный, не переставай молить Христа Бога спасти и помиловать души наши."},
  {"id": "ru-mol-0680", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0681", "section": "service", "who": "rubric", "text": "Мартиниану Палестинскому,"},
  {"id": "ru-mol-0682", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0683", "section": "service", "who": "reader", "text": "Перевод: Пламя искушений слёз потоками погасил ты, блаженный и, морские волнения и зверей движение обуздавший, взывал ты: «Препрославлен Ты, Всесильный, от огня и бури спасший меня»."},
  {"id": "ru-mol-0684", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0685", "section": "service", "who": "rubric", "text": "Мартирию Зеленецкому,"},
  {"id": "ru-mol-0686", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0687", "section": "service", "who": "reader", "text": "Перевод: С юности, в Боге блаженствующий, Христа возлюбив, ты оставил Отечество и от всей мирской суеты удалившись, в тихом пристанище досточтимой обители Богоматери ты оказался, оттуда увидев непроходимую пустыню, крестовидной зарей указанную, нашел ее подходящей, и в ней поселившись, монашествующих собрал и их своим учением, как лестницей восходящей на Небо, в неустанном труде старался ты приводить к Богу, Ему же молись, Богомудрый Мартирий, даровать душам нашим великую милость."},
  {"id": "ru-mol-0688", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0689", "section": "service", "who": "rubric", "text": "Мартирию, диакону Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0690", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0691", "section": "service", "who": "reader", "text": "Перевод: Прекрасно послуживший Господу в диаконском сане, почтенный иеродиакон Мартирий, и там как слуга Господень оказавшийся, где и Господь твой, молись Ему и о нас, да подаст нам великую милость."},
  {"id": "ru-mol-0692", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0693", "section": "service", "who": "rubric", "text": "Марфе Антиохийской, Едесской,"},
  {"id": "ru-mol-0694", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0695", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0696", "section": "service", "who": "rubric", "text": "Матроне Константинопольской,"},
  {"id": "ru-mol-0697", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0698", "section": "service", "who": "reader", "text": "Перевод: В мужском обличии укрывшись от вражеских лукавых путей, Матрона, к истинной жизни ты шествовала с неизменным стремлением и неуклонный жизненный путь Богомудро окончив, от Христа получила ты благодать духовную, потому и источаешь потоки исцелений всем с любовью приходящим в память твою славную, честь монахам, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0699", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0700", "section": "service", "who": "rubric", "text": "Меркурию Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0701", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0702", "section": "service", "who": "reader", "text": "Перевод: Желая удостоиться, блаженный, вечной жизни, праведно и непорочно ты проводил время своей земной жизни, потому, Меркурий, желаемого ты достиг, моли и нам удостоиться вечной жизни."},
  {"id": "ru-mol-0703", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0704", "section": "service", "who": "rubric", "text": "Меркурию Печерскому, еп. Смоленскому, в Ближних пещерах,"},
  {"id": "ru-mol-0705", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0706", "section": "service", "who": "reader", "text": "Перевод: Постом душу свою просветил ты, молитвами непрестанными сердце твое сосудом Духа Святого сделал ты, преподобный отче наш Меркурий, потому все вражеские войска ты мужественно победил и, как истинный победоносец, получил вознаграждение от Христа Бога. Ему помолись о душах наших."},
  {"id": "ru-mol-0707", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0708", "section": "service", "who": "rubric", "text": "Мефодию, игумену Пешношскому,"},
  {"id": "ru-mol-0709", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0710", "section": "service", "who": "reader", "text": "Перевод: Любовью к Богу с юности разжигаем, все мирские блага возненавидев, Христа Единого ты возлюбил и поэтому поселился в пустыни, создал в ней обитель и, собрав множество монахов, получил от Бога дар чудотворений, отче Мефодий, и был ты о Христе ревнитель и постник, как и преподобный Сергий, с ним же у Христа Бога испроси для православных христиан здоровья и спасения и душам нашим великую милость."},
  {"id": "ru-mol-0711", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0712", "section": "service", "who": "rubric", "text": "Михаилу Клопскому, Новгородскому,"},
  {"id": "ru-mol-0713", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0714", "section": "service", "who": "reader", "text": "Перевод: На земле Христа ради ты добровольно стал юродивым, мира этого красоту возненавидел и взыграния плоти обуздал постом и жаждой, лежанием на земле, от зноя же и мороза, дождя и снега и прочих природных трудностей никогда не уклоняясь, душу же ты очистил добродетелями, как золото в горниле, отче преподобный Богоносный Михаил, и сейчас на Небесах предстоишь Престолу Пресвятой Троицы. Но как имеющий дерзновение многое, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0715", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0716", "section": "service", "who": "rubric", "text": "Михаилу Малеину,"},
  {"id": "ru-mol-0717", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0718", "section": "service", "who": "reader", "text": "Перевод: На крыльях духовных к Боговедению разумно взлетев, мирскую суету ты оставил, блаженный, презрев мудрования плоти, ты искал Небесную мудрость, чтобы жить с Богом, и подал всем пример, говоря: «Хорошо жить с Богом», Михаил преподобный."},
  {"id": "ru-mol-0719", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0720", "section": "service", "who": "rubric", "text": "Михею Радонежскому,"},
  {"id": "ru-mol-0721", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0722", "section": "service", "who": "reader", "text": "Перевод: Иго Господа подняв на плечи (Мф.11:29-30), ты последовал за Христом с учителем своим преподобным Сергием, с ним же и удостоился видеть Пресвятую Богородицу. И слышал пресладкий голос Ее, обещавший не отступать от места этого, потому, преподобный Михей, молись о почитающих святую память твою."},
  {"id": "ru-mol-0723", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0724", "section": "service", "who": "rubric", "text": "Моисею Мурину,"},
  {"id": "ru-mol-0725", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0726", "section": "service", "who": "reader", "text": "Перевод: Пустынным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Моисей: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-0727", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0728", "section": "service", "who": "rubric", "text": "Моисею, чудотворцу Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0729", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0730", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0731", "section": "service", "who": "rubric", "text": "Моисею Угрину, Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0732", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0733", "section": "service", "who": "reader", "text": "Перевод: Трудам и подвигам борьбы со страстями, увидев чистоту твою, святой, кто не удивится? Ибо ты, принимая голод, заключение и раны, не стал рабом обольщения польки, но, как царь, владея своими страстями, сейчас и тогда прославился Всевидящим человеческие сердца, от Него же получил благодать помогать всем в искушениях, помогай и нам, почитающим твою память, Моисей преподобный."},
  {"id": "ru-mol-0734", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0735", "section": "service", "who": "rubric", "text": "Нестору Летописцу, Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0736", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0737", "section": "service", "who": "reader", "text": "Перевод: Великих князей русских деяния и преподобных отцов Печерских жития и чудеса описавший, свое же имя, Богомудрый Нестор, ради многих твоих добродетелей удостоившийся вписать на Небесах, моли и нам быть записанными в Книге Жизни."},
  {"id": "ru-mol-0738", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0739", "section": "service", "who": "rubric", "text": "Нестору Некнижному, Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0740", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0741", "section": "service", "who": "reader", "text": "Перевод: Чистый и праведный сердцем, и святой, преподобный Нестор, душой же ты был прост и не умел читать Писания, потому ты прилежно внимал читающим их и, соблюдая написанное в них, старался исполнять, и все это, как благоразумный, осуществив, обрел ты Царствие Небесное."},
  {"id": "ru-mol-0742", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0743", "section": "service", "who": "rubric", "text": "Никандру пустынножителю, Псковскому чдтв.,"},
  {"id": "ru-mol-0744", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "ru-mol-0745", "section": "service", "who": "reader", "text": "Перевод: Ты стал светилом незаходящего света для страны нашей, богоблаженный, доблестно претерпев бедствия от врага (диавола), избиения и раны стали для тебя одеждой нетления, ибо ты боролся со зверями и был ранен разбойниками, о них же молился, говоря: «Не вмени им этого греха», тем самым уподобившись Владыке Христу, достойный славы Никандр, отче наш, молись о душах наших."},
  {"id": "ru-mol-0746", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0747", "section": "service", "who": "rubric", "text": "Никите, столпнику Переславльскому,"},
  {"id": "ru-mol-0748", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0749", "section": "service", "who": "reader", "text": "Перевод: Православным разумом возненавидев юношеские страсти и начав мужественно подвизаться, ты победил врага, и в своем усердии угодил Богу, и свыше от Него получил дар чудотворений: прогонять бесов, исцелять болезни. Никита преславный, моли Христа Бога да спасет души наши."},
  {"id": "ru-mol-0750", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0751", "section": "service", "who": "rubric", "text": "Никите, Кириллу, Никифору, Клименту и Исаакию, братьям Алфановым (Сокольницким) в Новгороде,"},
  {"id": "ru-mol-0752", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0753", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0754", "section": "service", "who": "rubric", "text": "Никодиму Кожеезерскому,"},
  {"id": "ru-mol-0755", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0756", "section": "service", "who": "reader", "text": "Перевод: Ты переселился из царствующего города и великой его обители и, руководимый промышлением Божественного разума, устремился в сторону моря, поселился в пустыни, уклонясь от мирской суеты, и вооружился силой Святого Духа, прогоняя врагов своих оружием Креста и проводя жизнь в посте и постоянной молитве, подражая великим отцам Антонию, и Онуфрию, и Павлу Фивейскому, с ними же молись Господу, отче Никодим, о спасении душ наших."},
  {"id": "ru-mol-0757", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0758", "section": "service", "who": "rubric", "text": "Никодиму Святогорцу,"},
  {"id": "ru-mol-0759", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0760", "section": "service", "who": "reader", "text": "Перевод: Благодатью мудрости, отче, украшенный, ты стал Богогласной трубой Духа и наставником добродетелей, Никодим Богоглаголивый, ибо ты подаешь всем спасительные наставления, показывая сияние чистого жития богатством Боговдохновенных твоих поучений, ими же, как свет миру, ты воссиял."},
  {"id": "ru-mol-0761", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0762", "section": "service", "who": "rubric", "text": "Николе Святоше, князю Черниговскому, Печерскому чудотворцу, в Ближних пещерах,"},
  {"id": "ru-mol-0763", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0764", "section": "service", "who": "reader", "text": "Перевод: Отечество и славу княжения твоего оставил, Князю смирения, Христу, усердно последовал ты, преподобный отче наш Никола, потому получил от Него вечное царство и славу на Небесах, где радуясь, вспоминай нас, почитающих память твою с верой."},
  {"id": "ru-mol-0765", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0766", "section": "service", "who": "rubric", "text": "Никону, игумену Киево-Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0767", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0768", "section": "service", "who": "reader", "text": "Перевод: Ты стал ветвью Христова виноградника (Ин.15:5), Богоблаженный Никон, принося Ему как грозди добродетели свои и остальным указывая путь к добродетелям, приводя их ко Христу Богу. Ему же молим тебя, молись о душах наших."},
  {"id": "ru-mol-0769", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0770", "section": "service", "who": "rubric", "text": "Никону, игумену Радонежскому,"},
  {"id": "ru-mol-0771", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0772", "section": "service", "who": "reader", "text": "Перевод: Ты был ревнителем послушания, преподобный Никон всегда вспоминаемый, ибо прекрасный храм Святой Троицы в прославление отца твоего духовного воздвиг ты. Потому и мы, чада твои, с любовью взываем к тебе: «Слава Давшему тебе силу, слава Венчавшему тебя, слава Подающему через тебя всем исцеления»."},
  {"id": "ru-mol-0773", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0774", "section": "service", "who": "rubric", "text": "Никону Сухому, Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0775", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0776", "section": "service", "who": "reader", "text": "Перевод: Бога Благого возлюбив, монашеское ты принял житие и, прекрасно в нем подвизаясь, пленен был половцами, претерпел многие мучения, сильный духом Никон, благодатью Христовой освободился ты от них невидимо, и сейчас во Свете пребывая неприступном, молись о спасении нашем, память твою почитающих."},
  {"id": "ru-mol-0777", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0778", "section": "service", "who": "rubric", "text": "Нилу Мироточивому, Афонскому,"},
  {"id": "ru-mol-0779", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0780", "section": "service", "who": "reader", "text": "Перевод: Угодно Богу монашествовав на горе Афон, в молитвах и постах ты искал Бога и стал чистой обителью Духа, озаряя верующих лучами добродетелей, ими же освещаешь, Нил, взывающих к тебе: «Слава прославившему тебя Богу, слава Венчавшему тебя, слава Подающему через тебя всем исцеления»."},
  {"id": "ru-mol-0781", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0782", "section": "service", "who": "rubric", "text": "Нилу Постнику, Синайскому,"},
  {"id": "ru-mol-0783", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0784", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню, и стенаниями из глубины плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Нил, отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0785", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0786", "section": "service", "who": "rubric", "text": "Нилу Сорскому,"},
  {"id": "ru-mol-0787", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0788", "section": "service", "who": "reader", "text": "Перевод: Ты удалился от мира, скрываясь, как Давид (1Цар.23:14), и все мирское посчитав за грязь, и поселившись в тихом месте, ты наполнился духовной радостью, отче наш Нил, и захотел служить Единому Богу, расцвел, как пальма (Пс.91:13), и, как плодовитая лоза, ты увеличил количество монахов-пустынников. Потому мы с благодарностью восклицаем: «Слава Укрепившему тебя в подвиге пустынножительства, слава Избравшему тебя в России особым учредителем уставов для монахов-отшельников, слава молитвами твоими и нас Спасающему»."},
  {"id": "ru-mol-0789", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0790", "section": "service", "who": "rubric", "text": "Нилу Столобенскому,"},
  {"id": "ru-mol-0791", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0792", "section": "service", "who": "reader", "text": "Перевод: Как преяркий светильник явился ты на острове озера Селигер, преподобный отче Нил, ибо ты с юности, подняв на плечи Крест Христов, с усердием Ему последовал и чистотой приблизился к Богу, потому и обогатился дарованием чудес. Вот и мы, приходя к раке с мощами твоими, в сердечном сокрушении взываем: «Отче преподобный, моли Христа Бога о спасении наших душ»."},
  {"id": "ru-mol-0793", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0794", "section": "service", "who": "rubric", "text": "Олегу Брянскому, блгв. кн.,"},
  {"id": "ru-mol-0795", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0796", "section": "service", "who": "reader", "text": "Перевод: С юности возлюбил Христа всем сердцем, преподобный, славу земную, как временную, ты оставил, и царство земное посчитав ничем, радостно принял монашество и многими трудами город Брянск, как яркое солнце, озарил ты, потому стал украшением Троицы, моли, князь Олег, Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0797", "section": "service", "who": "rubric", "text": "Величание"},
  {"id": "ru-mol-0798", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0799", "section": "service", "who": "rubric", "text": "Онуфрию Великому,"},
  {"id": "ru-mol-0800", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0801", "section": "service", "who": "reader", "text": "Перевод: Духовным устремлением ты достиг пустыни, Богомудрый Онуфрий, и, как бесплотный, в ней многие годы трудолюбиво подвизался, подражая пророкам Илии и Иоанну Крестителю, и, из рук ангельских насладившись причащением Божественных Тайн, сейчас во свете Святой Троицы вместе с ними радуешься, моли о спасении нашем, твою память почитающих."},
  {"id": "ru-mol-0802", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0803", "section": "service", "who": "rubric", "text": "Онуфрию и Авксентию Вологодским,"},
  {"id": "ru-mol-0804", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0805", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0806", "section": "service", "who": "rubric", "text": "Онуфрию молчаливому и Онисиму затворнику, Печерским, в Ближних пещерах,"},
  {"id": "ru-mol-0807", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0808", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0809", "section": "service", "who": "rubric", "text": "Павлу Комельскому (Обнорскому),"},
  {"id": "ru-mol-0810", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0811", "section": "service", "who": "reader", "text": "Перевод: Любовью к Богу с юности разжигаем, Павел преподобный, все земные блага возненавидев, Христа единого ты возлюбил и ради Него поселился во внутреннюю пустынь, и жил со зверями, весь Христов. Поэтому Всевидящее Око, увидев твои труды, по преставлении обогатил тебя даром чудотворений. Потому взываем к тебе: «Моли непрестанно обо всех нас, почитаемую твою память всегда в молитвенных песнопениях прославляющих»."},
  {"id": "ru-mol-0812", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0813", "section": "service", "who": "rubric", "text": "Павлу Латрскому,"},
  {"id": "ru-mol-0814", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0815", "section": "service", "who": "reader", "text": "Перевод: Как поселившегося вместе с Бесплотными (ангелами) и всех преподобных собеседника, всеми прославляемый Павел, воспеваем тебя и молим: молись всегда о нас, чтобы мы обрели милость."},
  {"id": "ru-mol-0816", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0817", "section": "service", "who": "rubric", "text": "Павлу Послушливому, Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0818", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0819", "section": "service", "who": "reader", "text": "Перевод: Послушанию Христову подражавший, и ради имени Его во всяком послушании терпеливый, даже до смерти потрудившийся, Павел всеми почитаемый, воздаяние же за трудолюбие и послушание свое от Господа получил, Ему всегда молись о нас, воспевающих тебя."},
  {"id": "ru-mol-0820", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0821", "section": "service", "who": "rubric", "text": "Паисию Великому,"},
  {"id": "ru-mol-0822", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0823", "section": "service", "who": "reader", "text": "Перевод: Любовью к Богу с юности воспламеняем, преподобный, все мирские блага возненавидев, одного Христа ты возлюбил, ради этого поселился в пустыне, где удостоившись Божественного посещения, Его же и ангельскими глазами видеть тяжело, упав, поклонился. Великий же Податель даров, как Человеколюбец, сказал тебе: «Не ужасайся, возлюбленный Мой, дела твои угодны Мне, вот даю тебе дар: о каком грешнике ты помолишься, простятся ему грехи». Ты же в чистоте сердца твоего возгорелся, приняв воду и прикоснувшись к Неприкосновенному, омыл ноги Его и, испив воды, обогатился даром чудотворений, исцелять больных, прогонять от людей бесов и молитвой своей избавлять грешников от мучений. О преподобный отче Паисий, молю тебя, да молись и обо мне, как тебе обещал Бог, ибо из этих грешников я самый первый, да даст мне Господь время для покаяния и простит мои согрешения, так как Он Благой и Человеколюбивый, да вместе со всеми и я воспою Ему: «Аллилуйя»."},
  {"id": "ru-mol-0824", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0825", "section": "service", "who": "rubric", "text": "Паисию Величковскому,"},
  {"id": "ru-mol-0826", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0827", "section": "service", "who": "reader", "text": "Перевод: Ты был странником на земле и достиг Небесного Отечества, преподобный отче Паисий, Добротолюбия подвижник, верующих научил ты ум возводить к Богу и сердцем к Нему взывать: «Господи Иисусе Христе, Сыне Божий, помилуй мя, грешного»."},
  {"id": "ru-mol-0828", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0829", "section": "service", "who": "rubric", "text": "Паисию Галичскому,"},
  {"id": "ru-mol-0830", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0831", "section": "service", "who": "reader", "text": "Перевод: Сегодня воссияла нам память твоя, прославляемый Паисий, как сияющее солнце озаряет лучами весь мир, так и ты, преподобный, чудесами своими ночную тьму злых духов от нас отгоняешь. Сегодня Небесные силы, и святые Ангелы, и души праведных духовно торжествуют, радуясь. Сегодня и мы, грешные, преклоняясь перед твоим почитаемым образом, молимся: «О преподобный Паисий, моли не переставая Христа Бога о спасении города и людей, которые тебя почитают»."},
  {"id": "ru-mol-0832", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0833", "section": "service", "who": "rubric", "text": "Паисию Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0834", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0835", "section": "service", "who": "reader", "text": "Перевод: Подражая великому отцу Паисию, так же, как он в пустыню, ты поселился в пещеру, где подвиги совершая, блаженный, к трудам и пению псалмов всегда ты относился с усердием, моли о нас, воспевающих тебя."},
  {"id": "ru-mol-0836", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0837", "section": "service", "who": "rubric", "text": "Паисию Угличскому,"},
  {"id": "ru-mol-0838", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0839", "section": "service", "who": "reader", "text": "Перевод: Ради любви ко Христу ты оставил отечество и род и, устремившись к ангельскому житию, ты поселился в пустыни, в ней же явил многострадальную жизнь и принял от Бога дар чудотворений, Паисий преподобный, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0840", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0841", "section": "service", "who": "rubric", "text": "Паисию Хилендарскому (Болг.),"},
  {"id": "ru-mol-0842", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0843", "section": "service", "who": "reader", "text": "Перевод: Равноапостольного Кирилла язык ты, защитив, возродил и, приняв Троическое благословение Патриарха Евфимия, ты исполнил его. Ибо твоим трудом болгарам снова на понятном им языке проповедалось благочестие и тобой было начато по Промыслу Троическому дело освобождения народа Болгарского. Потому почитаем тебя, Паисий блаженный, и с любовью празднуем драгоценную память твою."},
  {"id": "ru-mol-0844", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0845", "section": "service", "who": "rubric", "text": "Палладию Александрийскому,"},
  {"id": "ru-mol-0846", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0847", "section": "service", "who": "reader", "text": "Перевод: Монашествовав Богоугодно, Богоносный отче наш, молитвой и постом Бога взыскал ты и был чистой обителью Духа, сияя верующим лучами добродетелей, просвещающими всех почитающих тебя. Слава прославившему тебя Христу, слава Укрепившему тебя, слава Подающему через тебя всем исцеления."},
  {"id": "ru-mol-0848", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0849", "section": "service", "who": "rubric", "text": "Памве, пустыннику Нитрийскому,"},
  {"id": "ru-mol-0850", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0851", "section": "service", "who": "reader", "text": "Перевод: В пустыне живущий в холщовых залатанных одеждах, и без тщеславия и внутренней суеты воспевая молитвы Богу, и явив собой образ человеческих добродетелей в научение, отче Памво, моли Христа Бога, да спасет души наши."},
  {"id": "ru-mol-0852", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0853", "section": "service", "who": "rubric", "text": "Памве, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0854", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0855", "section": "service", "who": "reader", "text": "Перевод: Прилежным послушанием и отвержением своей воли крепко себя обуздав, ты обрек себя на муки и раны за Христа Бога, от Него же особо, почитаемый всеми отче Памво, увенчался, молись о душах наших."},
  {"id": "ru-mol-0856", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0857", "section": "service", "who": "rubric", "text": "Панкратию Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0858", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0859", "section": "service", "who": "reader", "text": "Перевод: Панкратий Богомудрый, священник Господний прекрасный, чудеса многие сотворивший, молись Господу о спасении душ наших."},
  {"id": "ru-mol-0860", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0861", "section": "service", "who": "rubric", "text": "Параскеве Сербской,"},
  {"id": "ru-mol-0862", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0863", "section": "service", "who": "reader", "text": "Перевод: Пустынную и безмолвную жизнь возлюбив, и вослед Христа, Жениха твоего, усердно устремившись, и Его благое иго в юности твоей взяв, Крестным знамением на духовных врагов мужественно вооружившись, постническими подвигами, постом, молитвами и каплями слез ты погасила угли страстей, достойная славы Параскева, и сейчас в Небесном чертоге с мудрыми девами (Мф.25:1:13) предстоя Христу, моли о нас, почитающих святую память твою."},
  {"id": "ru-mol-0864", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0865", "section": "service", "who": "rubric", "text": "Пафнутию Боровскому,"},
  {"id": "ru-mol-0866", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0867", "section": "service", "who": "reader", "text": "Перевод: Просветив твое отечество светлостью жизни, в молитвах и постах ты наполнился дарами Святого Духа, и, во временной жизни прекрасно подвизаясь, ты открыл всем скорбящим щедроты милости и был защитником нищих. Потому молим тебя, отче Пафнутий, моли Христа Бога, да спасет души наши."},
  {"id": "ru-mol-0868", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0869", "section": "service", "who": "rubric", "text": "Пафнутию, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0870", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0871", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0872", "section": "service", "who": "rubric", "text": "Пахомию Великому,"},
  {"id": "ru-mol-0873", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0874", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню и из глубины стенаниями плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Пахомий, отче наш; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0875", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0876", "section": "service", "who": "rubric", "text": "Пахомию Нерехтскому,"},
  {"id": "ru-mol-0877", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0878", "section": "service", "who": "reader", "text": "Перевод: Житейскую суету ты отверг и, как птица, обрел для себя безмолвие в пустыни, в молитвах и бдении усердно трудился для Бога, преподобный отче Пахомий, и оставив прежнее место пребывания, ты отошел в пустынь, поселился в ней и создал обитель во имя Пресвятой Троицы, и расцвел, как пальма, и был примером духовного утешения. Потому, преподобный Пахомий, моли Пресвятую Троицу о спасении наших душ."},
  {"id": "ru-mol-0879", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0880", "section": "service", "who": "rubric", "text": "Петру Афонскому,"},
  {"id": "ru-mol-0881", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0882", "section": "service", "who": "reader", "text": "Перевод: Мир оставил ты, Петр, Господа ради своего и крест поднял на плечи свои, достиг Афонской горы, как ранее Илия Фесвитянин. И там пребывал в пощении, молитвах и бдении, умилостивляя Бога и представляя перед собой Пречистую Богородицу Молитвенницей, потому взываем к тебе: «Моли Христа Бога, да спасет наши души»."},
  {"id": "ru-mol-0883", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0884", "section": "service", "who": "rubric", "text": "Петру Коришскому, Сербскому,"},
  {"id": "ru-mol-0885", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0886", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0887", "section": "service", "who": "rubric", "text": "Петру, царевичу Ордынскому, Ростовскому,"},
  {"id": "ru-mol-0888", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0889", "section": "service", "who": "reader", "text": "Перевод: Отечества своего, блаженный Петр, удалившись, и богопротивную веру совершенно возненавидев, от тьмы к свету пришел ты и поселился в славном и многолюдном городе Ростове, в нем же, прожив почтенную жизнь, содействием Христовой благодати ты воздвиг храм во имя святых апостолов Петра и Павла, и украсив его, как невесту, чудесными иконами, удивил ты святителя и князя, и всех людей своей жизнью, потому и после смерти твоей Христос обогатил тебя даром чудотворений. Вспоминай нас, почитающих пресветлую память твою, преподобный отче Петр, и моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0890", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0891", "section": "service", "who": "rubric", "text": "Пимену Великому,"},
  {"id": "ru-mol-0892", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0893", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню и из глубины стенаниями плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Пимен, отче наш; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0894", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0895", "section": "service", "who": "rubric", "text": "Пимену Многоболезненному, Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0896", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0897", "section": "service", "who": "reader", "text": "Перевод: Богоносному Антонию смиренномудрием подражая, терпением уподобляясь Иову, не излечения болезни, но продолжения ее ты желал себе, твердый духом Пимен, чтобы не оказаться здоровым, но от места этого удаленным родителями и лишенным жизни рядом с преподобными и их чина, потому сверх надежды самими Ангелами был пострижен, с ними же моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0898", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0899", "section": "service", "who": "rubric", "text": "Пимену, постнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0900", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0901", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0902", "section": "service", "who": "rubric", "text": "Пиору, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0903", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-0904", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0905", "section": "service", "who": "rubric", "text": "Поликарпу Брянскому,"},
  {"id": "ru-mol-0906", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-0907", "section": "service", "who": "reader", "text": "Перевод: Парусом креста корабль души направляя, житейские блага оставил ты, и от мирской суеты удалился, телесные похоти умертвив, отче, многим воздержанием, пощением и слезами, молитвами и духовными песнопениями, непрестанно имея общение с Богом, потому и стал достойным жилищем Пресвятого Духа. Моли, Поликарп преподобный, Христа Бога, прощение прегрешений даровать нам и великую милость."},
  {"id": "ru-mol-0908", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0909", "section": "service", "who": "rubric", "text": "Поликарпу, архим. Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0910", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0911", "section": "service", "who": "reader", "text": "Перевод: Имени своему (Поликарп от греч. Πολύκαρπος — многоплодный) тождественный, как многоплодное дерево, насажден был в обители Божией Матери, многие и чудесные дела благоустройства трудами твоими явивший, мудрый Поликарп, моли Христа Бога о нас, чтобы и мы, принеся Ему много плодов добродетелей, спаслись."},
  {"id": "ru-mol-0912", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0913", "section": "service", "who": "rubric", "text": "Прокопию Декаполиту, исп.,"},
  {"id": "ru-mol-0914", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0915", "section": "service", "who": "reader", "text": "Перевод: Возделал своими слезами бесплодную пустыню и воздыханиями из глубины стократно возрастил плоды [веры], был светильником вселенной, сияя чудесами, Прокопий, отец наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0916", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0917", "section": "service", "who": "rubric", "text": "Прохору Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-0918", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0919", "section": "service", "who": "reader", "text": "Перевод: Преподобный чудотворец, отче Прохор, накормивший страдающих от голода хлебом из травы и солью из пепла, накорми и нас пищей духовной, моля Христа Бога о душах наших."},
  {"id": "ru-mol-0920", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0921", "section": "service", "who": "rubric", "text": "Роману Киржачскому,"},
  {"id": "ru-mol-0922", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0923", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0924", "section": "service", "who": "rubric", "text": "Руфу, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-0925", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0926", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0927", "section": "service", "who": "rubric", "text": "Савве Вишерскому, Новгородскому,"},
  {"id": "ru-mol-0928", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0929", "section": "service", "who": "reader", "text": "Перевод: С юности твоей весь Богу предал себя, блаженный, и ради любви к Нему отечество и родных оставил, в пустыни поселился, и в ней явив суровое житие, дарование чудотворений от Господа получил, Савва преподобный, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0930", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0931", "section": "service", "who": "rubric", "text": "Савве Крыпецкому, Псковскому,"},
  {"id": "ru-mol-0932", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0933", "section": "service", "who": "reader", "text": "Перевод: Ты стал прекрасным ростком пустыни, преподобный, ибо с юности и в мире предпочитал чистую жизнь, заботясь же о большем, и дом отеческий оставил ты, и всеми благами этого мира пренебрег, из другой страны ты пришел в обитель Богоспасаемого города Пскова и вверил себя в послушание преподобному Евфросину, потом, устремляясь разумом к лучшему, поселился ты в пустыни, в которой воздвиг почитаемую обитель, и собрал множество монахов, и наставил их на путь истинный. Потому и Христос, Которому ты принес себя в жертву, увидев твои прекрасные труды, как преяркого светильника, и после успения твоего обогатил тебя чудесами, Савва, отче наш. Молись же всегда Ему о стране нашей, о даровании ей победы над врагами, о том, чтобы стаду твоему пребывать защищенным от покушений врагов и всем нам спастись."},
  {"id": "ru-mol-0934", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0935", "section": "service", "who": "rubric", "text": "Савве Освященному,"},
  {"id": "ru-mol-0936", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0937", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню, и из глубины стенаниями плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Савва, отче наш; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0938", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0939", "section": "service", "who": "rubric", "text": "Савве Сторожевскому, Звенигородскому,"},
  {"id": "ru-mol-0940", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0941", "section": "service", "who": "reader", "text": "Перевод: С юности воспламеняем Божественной ревностью, ты возлюбил чистую жизнь, презрев суету и блага этого мира, последовал своему Богомудрому учителю, преблаженному Сергию, в труде, бдении, посте и подвиге: на Сторожи явился для безмолвия и духовной стражи, недремлющим предстоянием на Божественной страже ты обрел ум, созерцающий Бога и предвидящий демонские козни и нападения, принял в себя свет Пресвятого Духа и стал как преяркая звезда для всех верующих. Потому ты явился премудрым, несущим свет предстоятелем и пастырем стаду своему, просвещай светом твоим и всех, приходящих к тебе с верой, отче наш Савва, и моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0942", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0943", "section": "service", "who": "rubric", "text": "Савве и Алексию затворнику, Печерским, в Ближних пещерах,"},
  {"id": "ru-mol-0944", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0945", "section": "service", "who": "reader", "text": "Перевод: Преблаженные и Богоносные отцы наши Савва и Алексий, как приобретшие дерзновение ко Господу своей, подобной ангельской, жизнью, из-за которой обогатил Христос нетлением и чудесами мощи ваши, молим вас усердно: испросите очищение для наших душ и великую и богатую милость."},
  {"id": "ru-mol-0946", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0947", "section": "service", "who": "rubric", "text": "Савватию Соловецкому,"},
  {"id": "ru-mol-0948", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0949", "section": "service", "who": "reader", "text": "Перевод: Удалившись от мира и поселившись в пустыни, добрым подвигом ты подвизался, терпением напастей, вниманием и молитвами, потому и после смерти источаешь исцеления, Савватий отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0950", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0951", "section": "service", "who": "rubric", "text": "Сампсону странноприимцу,"},
  {"id": "ru-mol-0952", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0953", "section": "service", "who": "reader", "text": "Перевод: В терпении твоем обрел ты награду свою, отче преподобный, в молитвах постоянно пребывавший, нищих возлюбивший и им помогавший, молись Христу Богу, Сампсон милостивый блаженный о спасении душ наших."},
  {"id": "ru-mol-0954", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0955", "section": "service", "who": "rubric", "text": "Севастиану Карагандинскому, исп.,"},
  {"id": "ru-mol-0956", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-0957", "section": "service", "who": "reader", "text": "Перевод: Троицы Святой служитель, земной ангел и небесный человек, преемник духовного Оптинского старчества, исповедник, посвященный в Божественные тайны Христовы, почитаемая обитель Святого Духа, преподобный отче Севастиан, досточтимый, испроси мир для всего мира и душам нашим великую милость."},
  {"id": "ru-mol-0958", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0959", "section": "service", "who": "rubric", "text": "Севастиану Сохотскому, Пошехонскому,"},
  {"id": "ru-mol-0960", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0961", "section": "service", "who": "reader", "text": "Перевод: Удалившись от мира и поселившись в пустыни, добрым подвигом ты подвизался, суровой жизнью, бодрствованием и молитвами, потому и после смерти источаешь исцеления, Севастиан отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0962", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0963", "section": "service", "who": "rubric", "text": "Серапиону Псковскому,"},
  {"id": "ru-mol-0964", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0965", "section": "service", "who": "reader", "text": "Перевод: Избрав чистоту непорочности своим жизненным подвигом, Серапион, и все земные блага возненавидев, ты возлюбил Единого Христа. Поэтому поселился во внутреннюю пустынь и жил вместе со зверями, ты был постником, как Христос, и другом Евфросина, учителя твоего, потому и молим тебя, вспоминай нас, почитающих святую память твою, да взываем к тебе: «Радуйся, слава для пустынников, преподобный отче наш»."},
  {"id": "ru-mol-0966", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0967", "section": "service", "who": "rubric", "text": "Серафиму Саровскому чдтв.,"},
  {"id": "ru-mol-0968", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0969", "section": "service", "who": "reader", "text": "Перевод: С юности Христа возлюбил ты, преподобный, и Ему Одному послужить пламенно возжелав, в пустынном твоем житии постоянной молитвой и трудом подвизался ты, смиренным сердцем любовь Христову обретя, Небесным Серафимам в молитвенном песнословии помощник, в любви к обращающимся к тебе Христу подражатель, потому ты стал возлюбленным избранником Божией Матери, поэтому взываем к тебе: «Спасай нас молитвами твоими, радость наша, горячий перед Богом заступник, Серафим блаженный»."},
  {"id": "ru-mol-0970", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0971", "section": "service", "who": "rubric", "text": "Сергию Нуромскому, Вологодскому,"},
  {"id": "ru-mol-0972", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0973", "section": "service", "who": "reader", "text": "Перевод: Стремлением духовным воспламеняясь, пребогатый, слез твоих потоками душу свою напоил и стенаниями из глубины ранил сердце свое, и неусыпными молитвами, и всенощным предостоянием Владыке Христу принес многие плоды добродетелей. Потому как Божий угодник светло миру явился, сияя чудесами, Сергий отче наш, горячий молитвенник к Богу, всегда о нас Его моли, да спасет души наши."},
  {"id": "ru-mol-0974", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0975", "section": "service", "who": "rubric", "text": "Сергию, игумену Радонежскому, всея России чудотворцу,"},
  {"id": "ru-mol-0976", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0977", "section": "service", "who": "reader", "text": "Перевод: Добродетелей подвижник, ты, как истинный воин Христа Бога, против страстей крепко подвизался в жизни временной, в псалмопении, бдении и постах став примером для твоих учеников. Потому и вселился в тебя Пресвятой Дух: Его действием ты украшен светло. Но имея дерзновение ко Святой Троице, поминай стадо, собранное тобой премудро, и не забудь, как ты обещал, посещать детей твоих, Сергий, преподобный отче наш."},
  {"id": "ru-mol-0978", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0979", "section": "service", "who": "rubric", "text": "Тому же святому, на обретение мощей,"},
  {"id": "ru-mol-0980", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0981", "section": "service", "who": "reader", "text": "Перевод: Сегодня светло радуется царствующий город Москва, как лучезарным сиянием, молниями чудес твоих озаряем, всю вселенную созывает прославить тебя, Богомудрый Сергий. Почитаемая и славная обитель же твоя, которую во Имя Святой Троицы ты создал многими трудами твоими, отче, имея у себя стада учеников твоих, наполняется торжеством и радостью. Мы же, празднуя преславное обретение священных мощей твоих, сокрытых в земле, как благоухающий цветок и благовонное кадило, благоговейно их целуя, различные исцеления получаем и по твоим молитвам удостаиваемся прощения грехов, отче преподобный Сергий, моли Святую Троицу о спасении душ наших."},
  {"id": "ru-mol-0982", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0983", "section": "service", "who": "rubric", "text": "Сергию и Никону, Радонежским,"},
  {"id": "ru-mol-0984", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0985", "section": "service", "who": "reader", "text": "Перевод: Как от преяркого Солнца блистающие звезды, Троическим светом вы озаряете сердца верующих, став сосудами Света Пресвятой Троицы, и преудивительным вашим житием для монахов были неизменными законодателями и церквам украшение, и благоверным, и святителям и всем людям, ибо отогнав отсюда всю демонскую нечистоту своими чистыми учениями и делами, вы прекрасно упасли стадо, собранное вами, потому мы и сейчас молим вас: «Не забывайте о чадах своих, как имеющие дерзновение ко Святой Троице, Богомудрый Сергий с удивительным учеником своим Никоном, и молите Христа Бога, да спасет души наши»."},
  {"id": "ru-mol-0986", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0987", "section": "service", "who": "rubric", "text": "Сергию Шухтомскому,"},
  {"id": "ru-mol-0988", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-0989", "section": "service", "who": "reader", "text": "Перевод: Бденными молитвами и потоками слез ты напоил пустыню и стенаниями из глубины ее уплодородил, жизнь твоя была постнической и подобной Ангельской, ты претерпел борьбу и страдания от бесов и грубых людей и стал собеседником Ангелам, быв насадителем Божественного винограда, и, оставив временную жизнь, ты переселился в Небесное жилище. Потому почитаем тебя, преподобный отче наш Сергий, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-0990", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0991", "section": "service", "who": "rubric", "text": "Сергию и Герману, Валаамским чдтвв.,"},
  {"id": "ru-mol-0992", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-0993", "section": "service", "who": "reader", "text": "Перевод: Евангелия Христова настоящие послушники явились, преподобные, мир и все, что в нем, как несущественное, презрели ради любви Христовой, и поселились на морском острове, и трудолюбиво на нем подвизались против козней невидимых врагов, постом, бдением же и всенощным стоянием вы благоразумно подчинили плоть свою духу. Потому из правой руки Вседержителя получили достойные венцы и сейчас, предстоя Пресвятой Троице, молитесь, всеблаженные отцы Сергий и Герман, о сохранении в мире Отечества нашего и о спасении наших душ."},
  {"id": "ru-mol-0994", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0995", "section": "service", "who": "rubric", "text": "Силуану Афонскому,"},
  {"id": "ru-mol-0996", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-0997", "section": "service", "who": "reader", "text": "Перевод: Серафимской любви ко Господу пламенный ревнитель, и Иеремии, о народе плачущем, усердный подражатель, всеблаженный отче Силуан, ты, внимая зову Матери Господа сил, змея греховного с благоразумным мужеством изверг, и на гору Афонскую от суеты мира удалился, где в трудах и молитвах со слезами стяжал обильно благодать Святого Духа, ею же сердца наши воспламени и с тобой смиренно взывать укрепи:« Господь мой, Жизнь моя и Радость Святая, спаси мир и нас от всяких бедствий»."},
  {"id": "ru-mol-0998", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-0999", "section": "service", "who": "rubric", "text": "Силуану, схимнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-1000", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-1001", "section": "service", "who": "reader", "text": "Перевод: За усиленное воздержание и безграничное пощение ты принял свыше благодать чудотворения и обрел великое дерзновение к Богу, украшение постников, Силуан, молись Ему, да подаст нам мир и великую милость."},
  {"id": "ru-mol-1002", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1003", "section": "service", "who": "rubric", "text": "Сильвестру Обнорскому,"},
  {"id": "ru-mol-1004", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "ru-mol-1005", "section": "service", "who": "reader", "text": "Перевод: С молодых лет Христа возлюбив и с верой к Нему приблизившись, изнурил ты, живущий в пустыни, многострадальное тело твое. Потому, блаженный Сильвестр, с Ангелами торжествуя, моли Христа Бога даровать мир всему миру и будь помощником с верой призывающим тебя на помощь и почитающим святую память твою."},
  {"id": "ru-mol-1006", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1007", "section": "service", "who": "rubric", "text": "Симеону Новому Богослову,"},
  {"id": "ru-mol-1008", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-1009", "section": "service", "who": "reader", "text": "Перевод: Божественное озарение, отец Симеон, восприняв в душе твоей, ты оказался ярчайшим светом для мира, разгоняя его духовный мрак и всех убеждая искать благодать Духа, которую они потеряли. Моли настойчиво Бога даровать нам великую милость."},
  {"id": "ru-mol-1010", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1011", "section": "service", "who": "rubric", "text": "Симеону Столпнику,"},
  {"id": "ru-mol-1012", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1013", "section": "service", "who": "reader", "text": "Перевод: Ты был столпом терпения, подражая праотцам, преподобный: Иову — в терпении страданий, Иосифу — в перенесении искушений, и (ревнуя) житию бесплотных (ангелов), пребывая во плоти, Симеон отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-1014", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1015", "section": "service", "who": "rubric", "text": "Симеону Столпнику Дивногорцу,"},
  {"id": "ru-mol-1016", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1017", "section": "service", "who": "reader", "text": "Перевод: Пустынным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Симеон: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-1018", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1019", "section": "service", "who": "rubric", "text": "Симону Воломскому,"},
  {"id": "ru-mol-1020", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1021", "section": "service", "who": "reader", "text": "Перевод: С юности твоей устремив ум твой к Богу, блаженный Симон, ты отверг мир и поселился в непроходимую пустынь, и там, укрепляемый Господом, в молитвах и пощении доблестно прожил ты, и жизнь свою мученически закончил, убитый сынами противления (Еф.2:2). Потому ты увенчался вместе с преподобными и мучениками, с ними же и сейчас предстоишь Престолу Пресвятой Троицы. Моли Ее, молим тебя, подать прощение наших согрешений и даровать нам великую милость."},
  {"id": "ru-mol-1022", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1023", "section": "service", "who": "rubric", "text": "Симону Радонежскому,"},
  {"id": "ru-mol-1024", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-1025", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1026", "section": "service", "who": "rubric", "text": "Сисою Великому,"},
  {"id": "ru-mol-1027", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-1028", "section": "service", "who": "reader", "text": "Перевод: Телесные страсти умертвив воздержанием, ты распялся миру и, живя в пустыне, отсечением всех похотей стал как земной Ангел и Небесный человек, потому тебя как наставника монахов воспеваем, Сисой отче наш, и просим: «Моли Христа Бога, да спасет души наши»."},
  {"id": "ru-mol-1029", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1030", "section": "service", "who": "rubric", "text": "Сисою, схимнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-1031", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1032", "section": "service", "who": "reader", "text": "Перевод: Пустынным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Сисой: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-1033", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1034", "section": "service", "who": "rubric", "text": "Софии Суздальской,"},
  {"id": "ru-mol-1035", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1036", "section": "service", "who": "reader", "text": "Перевод: Небесной красотой ты ясно украшалась, ибо постническими трудами подвизалась, преподобная София, и была наследницей Небесного Царства, и вошла в Небесный Чертог, чтобы насладиться Христовой красотой, Его же моли о спасении города Суздаля от языческих нападений и междоусобной войны, и подай душам нашим великую милость."},
  {"id": "ru-mol-1037", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1038", "section": "service", "who": "rubric", "text": "Софронию, затворнику Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-1039", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1040", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1041", "section": "service", "who": "rubric", "text": "Спиридону и Никодиму, просфорникам Печерским, в Ближних пещерах,"},
  {"id": "ru-mol-1042", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1043", "section": "service", "who": "reader", "text": "Перевод: Просфоры (от греч. προσφορά — «приношение») руками своими творя, псалмопение непрестанное устами своими, как жертву благодарности (Пс.115:8) ты приносил Господу, вместе с почитаемым Никодимом, блаженный Спиридон, с ним же молись Христу Богу о душах наших."},
  {"id": "ru-mol-1044", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1045", "section": "service", "who": "rubric", "text": "Стефану Махрищскому,"},
  {"id": "ru-mol-1046", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1047", "section": "service", "who": "reader", "text": "Перевод: Православия ревнитель, благочестия наставник и чистоты, ищущим спасения путеводная звезда, монашествующих Богодухновенное украшение, преподобного Сергия духовный собеседник, Стефан премудрый, наставлениями и добрыми делами твоими души просветил ты и пустыни населил, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-1048", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1049", "section": "service", "who": "rubric", "text": "Стефану, игумену Печерскому, епископу Владимиро-Волынскому,"},
  {"id": "ru-mol-1050", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1051", "section": "service", "who": "reader", "text": "Перевод: Повинуясь учению Богоносного Феодосия, ты был поставлен им руководить святым его стадом, которое хорошо пас, церковь Богородицы, основанную по Ее воле чудесным образом, ты достойно построил, всегда вспоминаемый Стефан, в ней же нам, молящимся, испроси от Христа Бога великую милость."},
  {"id": "ru-mol-1052", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1053", "section": "service", "who": "rubric", "text": "Стефану Савваиту,"},
  {"id": "ru-mol-1054", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-1055", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1056", "section": "service", "who": "rubric", "text": "Стефану, в иночестве Симеону, царю Сербскому, Мироточивому,"},
  {"id": "ru-mol-1057", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-1058", "section": "service", "who": "reader", "text": "Перевод: Божественной благодатью просветившись, и после смерти ты являешь светлость жизни твоей, ибо источаешь благоухающее миро приходящим к раке с мощами твоими, и людей направляешь ты к свету Богоразумия, Симеон отче наш, Христа Бога моли даровать нам великую милость."},
  {"id": "ru-mol-1059", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1060", "section": "service", "who": "rubric", "text": "Стефану, в иночестве Симеону, царю Сербскому, Мироточивому и святителю Савве I, архиеп. Сербскому,"},
  {"id": "ru-mol-1061", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1062", "section": "service", "who": "reader", "text": "Перевод: Обители Хиландарской священных строителей и Афона светильников, Сербии похвалу, Симеона величайшего, преподобных украшение, и родственника его удивительного, святителя Савву, придите единогласно почтим, взывая: «Молите Христа Бога о пастве вашей, блаженные, и о том, чтобы Церкви быть свободной от бедствий»."},
  {"id": "ru-mol-1063", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1064", "section": "service", "who": "rubric", "text": "Титу, пресвитеру Печерскому, в Ближних пещерах,"},
  {"id": "ru-mol-1065", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1066", "section": "service", "who": "reader", "text": "Перевод: В любви к братии живущего тебя увидел ненавистник [диавол] и победил тебя, обратив во вражду, но знающий твои прежние труды Источник любви — Господь, снова переменил тебя к братолюбию, в нем ты и жил дальше, Богоугодный. Молись о нас, чтобы мы жили братолюбно."},
  {"id": "ru-mol-1067", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1068", "section": "service", "who": "rubric", "text": "Титу Печерскому, бывшему воину, в Дальних пещерах,"},
  {"id": "ru-mol-1069", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-1070", "section": "service", "who": "reader", "text": "Перевод: Воинство смертное оставив, стал одним из воинов в бессмертном воинстве Христове и оружием Его крестным победив бесов, победы венец от Христа, Тит, славно принял, Ему же молись даровать нам мир и великую милость."},
  {"id": "ru-mol-1071", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1072", "section": "service", "who": "rubric", "text": "Тихону Луховскому, Костромскому чдтв.,"},
  {"id": "ru-mol-1073", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1074", "section": "service", "who": "reader", "text": "Перевод: Устремлением духовным ты поселился в пустыни и там, безвозвратно шествуя Божественными путями, достиг ты Небесной обители, и сейчас, с Ангелами предстоишь у Престола Царя всех Христа Бога, Ему же настойчиво молись помиловать город этот и людей, с верой празднующих почитаемую память твою, Тихон преподобный, отче наш."},
  {"id": "ru-mol-1075", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1076", "section": "service", "who": "rubric", "text": "Тихону Медынскому, Калужскому,"},
  {"id": "ru-mol-1077", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1078", "section": "service", "who": "reader", "text": "Перевод: Как преяркий светильник явился ты в Российской земле, преподобный отче наш Тихон, поселился в пустыни, в ней же проводя суровую жизнь, ты был как бесплотный, потому и даром чудотворений обогатил тебя Бог. Так и мы, приходя к мощам твоим в сердечном сокрушении взываем: «Отче преподобный, моли Христа Бога о спасении наших душ»."},
  {"id": "ru-mol-1079", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1080", "section": "service", "who": "rubric", "text": "Трифону, архим. Вятскому,"},
  {"id": "ru-mol-1081", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1082", "section": "service", "who": "reader", "text": "Перевод: Как лучезарная звезда, просиял ты от востока до запада, ибо оставив отечество свое, дошел ты до Вятского края и Богоспасаемого города Хлынова, в нем же обитель во славу Пресвятой Богородицы создав и там к добродетели устремившись, собрал ты множество монахов, и, их направляя на путь спасения, был собеседником ангелов и соучастником постников, Трифон преподобный, с ними Христа Бога моли о спасении душ наших."},
  {"id": "ru-mol-1083", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1084", "section": "service", "who": "rubric", "text": "Трифону Печенгскому, Кольскому,"},
  {"id": "ru-mol-1085", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1086", "section": "service", "who": "reader", "text": "Перевод: Пути, ведущего к жизни, наставник и учитель ты был, ибо сначала, преподобный отче наш Трифон, пришел ты в Норвежскую землю, а потом и в самых дальних концах северного края ты просветил народы, породив их (в Крещении) водой и Духом Святым, и насадил священные чада твои, как масличные деревья в бесплодной пустыни, создал великую обитель Святой и Живоначальной, Единосущной и Нераздельной Троицы, собрав множество монахов. Потому, почитая тебя равным с апостолами и пустынножителями, усердно коленопреклоненно взываем: моли Бога всех о русской земле, о крае твоем и обо всех людях, почитающих память твою."},
  {"id": "ru-mol-1087", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1088", "section": "service", "who": "rubric", "text": "Феодору Начертанному, исп.,"},
  {"id": "ru-mol-1089", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1090", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и чистоты, светильник вселенной, архиереев Богодухновенное украшение, Феодор премудрый, учениями твоими ты всех просветил, лира духовная; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-1091", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1092", "section": "service", "who": "rubric", "text": "Феодору Освященному,"},
  {"id": "ru-mol-1093", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1094", "section": "service", "who": "reader", "text": "Перевод: Пустынным жителем, и во плоти Ангелом, и чудотворцем явился ты, Богоносный отче наш Феодор: постом, бдением, молитвою небесные дарования стяжав, исцеляешь ты болящих и души с верою прибегающих к тебе. Слава Давшему тебе силу, слава Увенчавшему тебя, слава Совершающему через тебя всем исцеления."},
  {"id": "ru-mol-1095", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1096", "section": "service", "who": "rubric", "text": "Феодору, кн. Острожскому, Печерскому, в Дальних пещерах,"},
  {"id": "ru-mol-1097", "section": "service", "who": "rubric", "text": "глас 7"},
  {"id": "ru-mol-1098", "section": "service", "who": "reader", "text": "Перевод: Ты преобразил славу земного княжения в смиренный образ монашества, и вместо видимых врагов вооружился против невидимых и, явившись прекрасным победителем и тех и других, ты стал одним из чудотворцев Печерских, потому и для нас испроси дар ревности Божией, любовью к ближним сердца наши просвети и ко спасению вечному пути наши, Феодор блаженный, направь."},
  {"id": "ru-mol-1099", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1100", "section": "service", "who": "rubric", "text": "Феодору Сикеоту, еп. Анастасиупольскому,"},
  {"id": "ru-mol-1101", "section": "service", "who": "rubric", "text": "глас 2"},
  {"id": "ru-mol-1102", "section": "service", "who": "reader", "text": "Перевод: С пеленок был освящен и наполнен благодатью, ты осветил мир чудесами и отгнал множество демонов, совершитель священного служения Феодор, потому молись о нас Господу."},
  {"id": "ru-mol-1103", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1104", "section": "service", "who": "rubric", "text": "Феодору Студиту, исп.,"},
  {"id": "ru-mol-1105", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1106", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и чистоты, светильник вселенной, архиереев Богодухновенное украшение, Феодор премудрый, учениями твоими ты всех просветил, лира духовная; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-1107", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1108", "section": "service", "who": "rubric", "text": "Феодору и Павлу Ростовским,"},
  {"id": "ru-mol-1109", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1110", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1111", "section": "service", "who": "rubric", "text": "Феодосию Великому, общих житий начальнику,"},
  {"id": "ru-mol-1112", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1113", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню, и стенаниями из глубины плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Феодосий, отче наш, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-1114", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1115", "section": "service", "who": "rubric", "text": "Феодосию Едесскому, Столпнику,"},
  {"id": "ru-mol-1116", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-1117", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1118", "section": "service", "who": "rubric", "text": "Феодосию Кавказскому,"},
  {"id": "ru-mol-1119", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1120", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1121", "section": "service", "who": "rubric", "text": "Феодосию, игумену Киево-Печерскому,"},
  {"id": "ru-mol-1122", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1123", "section": "service", "who": "reader", "text": "Перевод: Возвысившись в добродетели, с юности возлюбив монашеское житие, ты исполнения своего желания доблестно достиг, в пещеру вселившись; и, украсив житие твое постом и чистотою, в молитвах, как бесплотный, пребывал, в Российской земле, как яркое светило просияв, отче Феодосий; моли Христа Бога спастись душам нашим."},
  {"id": "ru-mol-1124", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1125", "section": "service", "who": "rubric", "text": "Феодосию Терновскому,"},
  {"id": "ru-mol-1126", "section": "service", "who": "rubric", "text": "глас 3"},
  {"id": "ru-mol-1127", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1128", "section": "service", "who": "rubric", "text": "Феодосию Тотемскому,"},
  {"id": "ru-mol-1129", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1130", "section": "service", "who": "reader", "text": "Перевод: С юности, преподобный Феодосий, ты устремил свое желание ко Христу Богу, ради Него оставил город и отечество твое и суетную славу оценив как прах, последовал ты преподобному Димитрию и подвизался в его обители, переселился к городу Тотьме и поселился у реки, постом, бдением, ношением власяницы и вериг тело свое ты отягощал. Потому Бог, видя твои труды, после преставления твоего обогатил тебя даром чудотворений: ты изгоняешь бесов и даешь зрение слепым, от всяких недугов и бед избавляешь приходящих к тебе с верой и взывающих: «Слава Давшему тебе силу, слава Венчавшему тебя, слава Подающему через тебя всем исцеления»."},
  {"id": "ru-mol-1131", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1132", "section": "service", "who": "rubric", "text": "Феоктисту Палестинскому,"},
  {"id": "ru-mol-1133", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1134", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню, и из глубины стенаниями плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Феоктист, отче наш; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-1135", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1136", "section": "service", "who": "rubric", "text": "Феоктисту, бывшему Драгутину, королю Сербскому,"},
  {"id": "ru-mol-1137", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1138", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1139", "section": "service", "who": "rubric", "text": "Феофану, исп., еп. Никейскому,"},
  {"id": "ru-mol-1140", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1141", "section": "service", "who": "reader", "text": "Перевод: Православия наставник, благочестия учитель и чистоты, вселенной светильник, архиереев Богодухновенное украшение, Феофан премудрый, учениями твоими всех просветил ты, лира духовная, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-1142", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1143", "section": "service", "who": "rubric", "text": "Феофану исп., Сигрианскому,"},
  {"id": "ru-mol-1144", "section": "service", "who": "rubric", "text": "глас 5"},
  {"id": "ru-mol-1145", "section": "service", "who": "reader", "text": "Перевод: Ты украсил свою жизнь воздержанием и телесные страсти умертвив, победил ты вражеские козни, отец Феофан, преставился ты к Богу и жизни вечной, как достойный наследник, молясь непрестанно о помиловании душ наших."},
  {"id": "ru-mol-1146", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1147", "section": "service", "who": "rubric", "text": "Феофилу, архиеп. Новгородскому, в Дальних пещерах,"},
  {"id": "ru-mol-1148", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1149", "section": "service", "who": "reader", "text": "Перевод: Правилом веры и образом кротости, воздержания известным учителем ты воистину был для Христова стада, уча его смирению, а не отвлеченному мудрствованию, потому и обрел то, что желал, отче святитель Феофил, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-1150", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1151", "section": "service", "who": "rubric", "text": "Феофилакту исп., еп. Никомидийскому,"},
  {"id": "ru-mol-1152", "section": "service", "who": "rubric", "text": "глас 6"},
  {"id": "ru-mol-1153", "section": "service", "who": "reader", "text": "Перевод: Скрываясь [от мира] ты жил, достойный всяческих похвал, но Христос тебя всем показал, как свечу на подсвечнике духовном и вручил тебе заветы учений Духа Святого, ими же, святитель Феофилакт, и нас просвети."},
  {"id": "ru-mol-1154", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1155", "section": "service", "who": "rubric", "text": "Ферапонту Белоезерскому, Можайскому,"},
  {"id": "ru-mol-1156", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1157", "section": "service", "who": "reader", "text": "Перевод: Жизнью чистой просветился, в молитвах и постах ты явился прекрасным произрастанием пустыни и, последуя духовному твоему учителю, к Небесному ум свой направил, стаду твоему ты был наставником, потому молим тебя, отче Ферапонт, моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-1158", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1159", "section": "service", "who": "rubric", "text": "Ферапонту Монзенскому,"},
  {"id": "ru-mol-1160", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1161", "section": "service", "who": "reader", "text": "Перевод: Любовью Христовой, Богомудрый, просветившись, ты подражал добродетелями Василию блаженному, всякое же телесное наслаждение возненавидев и вселившись в пустынь, там ты особо подвизался в молитвенном пении, бдении и пощении. Потому Христос и обогатил тебя даром чудес. Вспоминай нас, почитающих пресветлую память твою, преподобный отче Ферапонт, и моли Христа Бога о спасении наших душ."},
  {"id": "ru-mol-1162", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1163", "section": "service", "who": "rubric", "text": "Филиппу Ирапскому,"},
  {"id": "ru-mol-1164", "section": "service", "who": "rubric", "text": "глас 4"},
  {"id": "ru-mol-1165", "section": "service", "who": "reader", "text": "Перевод: Как кедр, по-псаломски растущий в пустыне, и как цветущая пальма благоухающая (Пс.91:13), подражатель учителя твоего был ты, преподобного отца Корнилия, ибо по стопам его последовал и, святое иго взяв, светлым житием просиял ты, как солнце, и явил миру много чудес, отче Филипп! И сейчас на Небесах ты предстоишь Престолу Пресвятой Троицы и, как имеющий великое дерзновение, преподобные руки свои воздев, моли от врагов сохраниться городам нашим и спастись душам нашим."},
  {"id": "ru-mol-1166", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1167", "section": "service", "who": "rubric", "text": "Фоме Малеину и Акакию Синайскому,"},
  {"id": "ru-mol-1168", "section": "service", "who": "rubric", "text": "глас 1"},
  {"id": "ru-mol-1169", "section": "service", "who": "reader", "text": "Перевод: Светила Богом явленные миру и монахов духовное сияние, Фома — чудесами, Акакий же послушанием просияли ярко, их, как имеющих дерзновение к Богу, просим помочь молитвами в битвах, да просят они у Христа Бога даровать прощение согрешений почитающим их святую память."},
  {"id": "ru-mol-1170", "section": "service", "who": "rubric", "text": "* *"},
  {"id": "ru-mol-1171", "section": "service", "who": "rubric", "text": "Харитону Исповеднику,"},
  {"id": "ru-mol-1172", "section": "service", "who": "rubric", "text": "глас 8"},
  {"id": "ru-mol-1173", "section": "service", "who": "reader", "text": "Перевод: Слез твоих потоками ты возделал бесплодную пустыню, и стенаниями из глубины плод трудов своих умножил во сто крат, и сделался светилом вселенной, сияя чудесами, Харитон, отче наш, моли Христа Бога о спасении душ наших."},
];

